#!/usr/bin/env python3
"""台指期「快速修復回檔」策略 —— 每日訊號（明日作戰表）→ Discord，單檔可執行。

    pip install finlab pandas tzdata
    export Finlab_API_token=...            # FinLab API token
    export DISCORD_WEBHOOK_URL=...         # Discord webhook
    python3 tx_daily_signal.py             # 送出精簡版
    python3 tx_daily_signal.py --full      # 六個區塊的完整版
    python3 tx_daily_signal.py --dry-run --as-of 2025-05-12 --full   # 回放某一天
    python3 tx_daily_signal.py notify --webhook ... --title ... --text ...   # 失敗通知（只用標準函式庫）

注碼規則（最終套件，docs/final_package.md）
    進場日收盤 < MA200 → 固定 3x；≥ MA200 → 4% ÷ 停損距離、上限 2.5x
    3x 部位權益 +150% → 減碼到 1x（step-down）；空手且收盤 > MA200 → 核心 0.5x
`--sizing risk --no-step-down` 可切回舊版注碼。

程式碼（策略、注碼、訊息）從 repo 逐字嵌入，換倉價差嵌入 332 筆歷史值，
新換倉日自動向期交所補抓。由 scripts/make_daily_script.py 產生；改了程式請重新產生。
"""

from __future__ import annotations

import os
import pathlib
import sys

_SOURCES = {}
_SOURCES['tw_backdraw/bars.py'] = '"""日線資料結構與讀檔。"""\n\nfrom __future__ import annotations\n\nimport csv\nfrom dataclasses import dataclass\nfrom datetime import date, datetime\nfrom pathlib import Path\n\n\n@dataclass(frozen=True)\nclass Bar:\n    d: date\n    open: float\n    high: float\n    low: float\n    close: float\n\n    @property\n    def iso(self) -> str:\n        return self.d.isoformat()\n\n\ndef _parse_date(raw: str) -> date:\n    raw = raw.strip()\n    for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%Y%m%d"):\n        try:\n            return datetime.strptime(raw, fmt).date()\n        except ValueError:\n            continue\n    raise ValueError(f"無法解析日期: {raw!r}")\n\n\ndef load_csv(path: str | Path) -> list[Bar]:\n    """讀取日線 CSV。\n\n    必要欄位: date, close。open/high/low 缺漏時以 close 補齊，\n    這樣只有收盤價的資料集也能直接跑（策略訊號全部以收盤價判定）。\n    """\n    bars: list[Bar] = []\n    with open(path, newline="", encoding="utf-8-sig") as fh:\n        for row in csv.DictReader(fh):\n            row = {(k or "").strip().lower(): (v or "").strip() for k, v in row.items()}\n            if not row.get("date") or not row.get("close"):\n                continue\n            close = float(row["close"].replace(",", ""))\n\n            def pick(key: str) -> float:\n                val = row.get(key, "")\n                return float(val.replace(",", "")) if val else close\n\n            bars.append(\n                Bar(\n                    d=_parse_date(row["date"]),\n                    open=pick("open"),\n                    high=pick("high"),\n                    low=pick("low"),\n                    close=close,\n                )\n            )\n    bars.sort(key=lambda b: b.d)\n    if not bars:\n        raise ValueError(f"{path} 沒有可用的日線資料")\n    return bars\n'
_SOURCES['tw_backdraw/config.py'] = '"""策略參數。\n\n所有可調參數集中於此，方便做敏感度測試。\n預設值對應貼文中的歷史統計（12 國、近百年、174 次樣本）。\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\n\n\n@dataclass(frozen=True)\nclass SetupConfig:\n    """「快速修復」劇本的辨識條件。"""\n\n    # 先要有一段像樣的回檔才談得上修復，貼文樣本為 -16%\n    min_drawdown: float = 0.10\n    # 從谷底起算，補回跌幅的多少比例才算「補回來了」。\n    # 貼文的原始值是 0.75；預設改用 grid search 以「總報酬 ÷ 最大回檔」選出的 0.60。\n    repair_fraction: float = 0.60\n    # 補回必須在幾個交易日內完成。\n    # 貼文的原始值是 15（對應「89% 創高」那一組）；預設改用 0.60/30 這組。\n    max_repair_bars: int = 30\n    # 訊號有效期；超過仍未創高也未失效就自然過期\n    setup_expiry_bars: int = 120\n    # 修復視窗過期後，把參考高點重新錨定到「谷底之後的波段高」。\n    # 關掉的話，參考高點會一直釘在舊高，直到指數重新站上它為止 ——\n    # 台股 2000 年頭部之後花了 17.3 年才收復 10,202，等於中間完全看不到訊號。\n    reanchor_on_expiry: bool = True\n\n\n@dataclass(frozen=True)\nclass LevelConfig:\n    """由 P（前高）與 T（谷底）推出的關鍵價位。"""\n\n    # 主防線：補回一半\n    half_line_ratio: float = 0.50\n    # 警戒線：貼文的原始值是 0.382（台股 42916）。\n    # 預設改用 0.500 —— 這會讓警戒線與主防線重合，\n    # 等於「跌破補回一半的線（含 0.5% 緩衝）就全部出場」，是明顯更緊的停損。\n    warn_line_ratio: float = 0.500\n    # 允許對主防線的假跌破緩衝（貼文：一半案例跌破不到 0.5%）\n    half_line_buffer: float = 0.005\n\n\n@dataclass(frozen=True)\nclass EntryConfig:\n    """分批進場梯。\n\n    核心前提：歷史上回檔中位數只有 2.9%、四分之三不超過 5%，\n    所以「等深回檔」的期望值是負的 —— 底倉先上車，回檔才是加碼機會。\n    """\n\n    # 訊號確認後隔日直接建立的底倉權重。\n    # 貼文原意是 0.40（保留兩段回檔加碼空間）；預設改用 1.00，\n    # 也就是訊號一確認就把目標水位一次買足，不留加碼梯。\n    base_weight: float = 1.00\n    # (自訊號後波段高點的回檔幅度, 加碼權重)\n    pullback_ladder: tuple[tuple[float, float], ...] = ((0.03, 0.30), (0.05, 0.30))\n    # 幾個交易日內若都沒等到回檔，就以市價補齊剩餘部位（不參與才是最大風險）。\n    # 註：預設 base_weight=1.00 時沒有加碼梯，本參數不影響任何決策；\n    # grid search 對它的取值也近乎均勻分布（10/20/40 各約三分之一），維持 20 為中性值。\n    fill_timeout_bars: int = 20\n    # 突破前高後補齊剩餘部位。\n    # 預設 True：訊號觸發時距前高通常只剩 3~4%，等不到回檔梯就先創高是常態，\n    # 若此時取消加碼，實際部署會長期停在底倉水位（實測平均僅 24%）。\n    # 往上買的單位風險較高，引擎會按停損距離自動縮小這一段的權重。\n    breakout_fills_remainder: bool = True\n\n\n@dataclass(frozen=True)\nclass ExitConfig:\n    """出場與風控。"""\n\n    # 收盤跌破警戒線 → 減碼比例。\n    # 貼文原意是 0.50（砍一半、保留船票）；預設改用 1.00，也就是跌破就全部出場。\n    # 這會降低勝率、提高總報酬與報酬÷回檔（見 docs/strategy.md §11）。\n    warn_derisk_fraction: float = 1.00\n    # 收盤跌破谷底 → 全出（貼文中 11% 的失敗案例都是大熊市開場）\n    hard_stop_at_trough: bool = True\n    # 觸及前高後先落袋的比例。\n    # 預設 0：「離前高很近，本身不是賣出的理由」——前高只是統計上的高機率目標，\n    # 不是出場訊號；獲利全部交給停利機制處理。設 1/3 可改回分批落袋。\n    target_take_fraction: float = 0.0\n\n    # 創高之後用哪一種停利：\n    #   "trail"       自創高後最高收盤回檔 trail_drawdown → 出場\n    #   "ma_ratchet"  停利價 = max(前高, MA)。創高後先把前高當出場線，\n    #                 等 MA 爬過前高，就改看 MA 跌破 —— 均線只會把出場線往上推。\n    #   "both"        兩者取較緊（較高）的那一條\n    exit_mode: str = "trail"\n    # ma_ratchet / both 使用的均線天期（以加權指數收盤計）\n    ma_period: int = 20\n    # trail / both 使用的回檔幅度（以指數計）\n    trail_drawdown: float = 0.08\n\n\n@dataclass(frozen=True)\nclass SizingConfig:\n    """部位規模（標的為 2 倍槓桿 ETF，必須以指數停損距離反推）。"""\n\n    # 單筆交易願意承受的權益風險（兩段式停損全走完的預期損失）\n    risk_per_trade: float = 0.08\n    # 標的槓桿倍數（台灣50正2 = 2）\n    leverage: float = 2.0\n    # 最高持股水位（佔權益比例）\n    max_weight: float = 1.0\n    # 停損距離至少視為這麼大，避免訊號日離谷底太近而算出過大部位\n    min_stop_distance: float = 0.05\n\n\n@dataclass(frozen=True)\nclass CostConfig:\n    """台股 ETF 交易成本與槓桿 ETF 的內扣損耗。"""\n\n    # 券商手續費 0.1425% × 折扣\n    fee_rate: float = 0.001425\n    fee_discount: float = 0.60\n    # ETF 賣出證交稅 0.1%\n    tax_rate: float = 0.001\n    # 槓桿 ETF 年化內扣（管理費 + 期貨轉倉/避險成本）\n    annual_carry: float = 0.012\n    trading_days: int = 252\n\n    @property\n    def buy_cost(self) -> float:\n        return self.fee_rate * self.fee_discount\n\n    @property\n    def sell_cost(self) -> float:\n        return self.fee_rate * self.fee_discount + self.tax_rate\n\n    @property\n    def daily_carry(self) -> float:\n        return self.annual_carry / self.trading_days\n\n\n@dataclass(frozen=True)\nclass StrategyConfig:\n    setup: SetupConfig = field(default_factory=SetupConfig)\n    levels: LevelConfig = field(default_factory=LevelConfig)\n    entry: EntryConfig = field(default_factory=EntryConfig)\n    exit: ExitConfig = field(default_factory=ExitConfig)\n    sizing: SizingConfig = field(default_factory=SizingConfig)\n    cost: CostConfig = field(default_factory=CostConfig)\n\n\n# ---------------------------------------------------------------------------\n# 預設組（PRESETS）\n#\n# 以下各組是 648,000 組 grid search + 樣本外驗證（scripts/grid_search.py、\n# scripts/walk_forward.py）的產物。**預設是 tuned**，也就是以總報酬為目標\n# 選出來的那一組；忠於貼文的原始設定保留在 `post`。\n# 兩者的取捨與已知風險記在 docs/strategy.md §11，換組合前請先讀。\n# ---------------------------------------------------------------------------\n\n#: 以「總報酬 ÷ 最大回檔」為目標選出的參數（本專案的預設）。\n#: 放寬訊號定義（30 日 / 補回 60%）、訊號確認即滿倉、跌破主防線全數出場。\n#: 樣本內 21 筆、勝率 57%、總報酬 +2232%、最大回檔 -35.8%、比值 62.4。\n#: 樣本外驗證中，這個目標函數的表現優於直接用總報酬（見 docs/strategy.md §11）。\nTUNED_CONFIG = StrategyConfig()\n\nDEFAULT_CONFIG = TUNED_CONFIG\n\n#: 忠於貼文的原始設定：15 日內補回 75%、底倉四成留加碼梯、\n#: 38.2% 回補位減碼一半。樣本內 8 筆、勝率 50%、總報酬 +31.4%、最大回檔 -20.4%。\nPOST_CONFIG = StrategyConfig(\n    setup=SetupConfig(repair_fraction=0.75, max_repair_bars=15),\n    levels=LevelConfig(warn_line_ratio=0.382),\n    entry=EntryConfig(base_weight=0.40),\n    exit=ExitConfig(warn_derisk_fraction=0.50),\n)\n\n#: 調校過的訊號 + MA40 棘輪出場。用報酬換勝率與較小的回檔：\n#: 樣本內 21 筆、勝率 67%、總報酬 +459%、回檔 -35%。\nBALANCED_CONFIG = StrategyConfig(\n    exit=ExitConfig(warn_derisk_fraction=1.0, exit_mode="ma_ratchet", ma_period=40),\n)\n\n#: 全網格勝率最高的一組。**它是靠關掉兩道停損換來的**，總報酬遠低於預設組。\n#: 列在這裡是為了讓「最大化勝率」的後果可以被重現，不是建議值。\nWINRATE_CONFIG = StrategyConfig(\n    setup=SetupConfig(min_drawdown=0.13),\n    levels=LevelConfig(warn_line_ratio=0.382),\n    entry=EntryConfig(fill_timeout_bars=40),\n    exit=ExitConfig(warn_derisk_fraction=0.0, hard_stop_at_trough=False,\n                    exit_mode="ma_ratchet", ma_period=40),\n)\n\n#: 美股版（S&P 500 訊號 → UPRO 3x 執行）以「總報酬 ÷ 最大回檔」選出的參數。\n#: 與台股版的差異：回檔門檻 7%（S&P 500 在 FinLab 涵蓋的 10.6 年裡 ≥10% 的\n#: 回檔太少）、移動停利放寬到 10%（3 倍槓桿的波動較大）。\n#: 樣本內 8 筆、勝率 62%、總報酬 +627%、最大回檔 -37.5%、比值 16.7。\n#: ⚠️ min_drawdown 落在搜尋網格的下界，最佳值可能在網格之外 —— 見 docs/strategy.md §12。\nUS_TUNED_CONFIG = StrategyConfig(\n    setup=SetupConfig(min_drawdown=0.07, repair_fraction=0.60, max_repair_bars=30),\n    levels=LevelConfig(warn_line_ratio=0.500),\n    entry=EntryConfig(base_weight=1.0, fill_timeout_bars=10),\n    exit=ExitConfig(warn_derisk_fraction=1.0, exit_mode="trail", trail_drawdown=0.10),\n    sizing=SizingConfig(leverage=3.0),\n    cost=CostConfig(fee_rate=0.0, fee_discount=1.0, tax_rate=0.0, annual_carry=0.0091),\n)\n\n#: NASDAQ 版（^IXIC 訊號 → TQQQ 3x 執行）以「總報酬 ÷ 最大回檔」選出的參數。\n#: 樣本內 8 筆、勝率 88%、總報酬 +933%、最大回檔 -30.8%、比值 30.3。\n#:\n#: ⚠️ trail_drawdown=0.12 是**尖峰而非平台**：鄰近值的比值為 10%→19.0、\n#: 12%→30.3、15%→15.7，且交易數從 12 筆掉到 8 筆。這是過擬合的典型特徵，\n#: 較穩健的鄰居是 trail=0.08（16 筆、比值 21.3）。詳見 docs/strategy.md §13。\nNQ_TUNED_CONFIG = StrategyConfig(\n    setup=SetupConfig(min_drawdown=0.07, repair_fraction=0.60, max_repair_bars=30),\n    levels=LevelConfig(warn_line_ratio=0.382),\n    entry=EntryConfig(base_weight=1.0, fill_timeout_bars=10),\n    exit=ExitConfig(warn_derisk_fraction=1.0, exit_mode="trail", trail_drawdown=0.12),\n    sizing=SizingConfig(leverage=3.0),\n    cost=CostConfig(fee_rate=0.0, fee_discount=1.0, tax_rate=0.0, annual_carry=0.0095),\n)\n\n#: 同上但把移動停利改成鄰域穩健的 8%：16 筆、勝率 62%、+570%、-26.8%、比值 21.3。\nNQ_ROBUST_CONFIG = StrategyConfig(\n    setup=NQ_TUNED_CONFIG.setup, levels=NQ_TUNED_CONFIG.levels,\n    entry=NQ_TUNED_CONFIG.entry,\n    exit=ExitConfig(warn_derisk_fraction=1.0, exit_mode="trail", trail_drawdown=0.08),\n    sizing=NQ_TUNED_CONFIG.sizing, cost=NQ_TUNED_CONFIG.cost,\n)\n\nPRESETS: dict[str, StrategyConfig] = {\n    "tuned": TUNED_CONFIG,\n    "post": POST_CONFIG,\n    "balanced": BALANCED_CONFIG,\n    "winrate": WINRATE_CONFIG,\n    "us_tuned": US_TUNED_CONFIG,\n    "nq_tuned": NQ_TUNED_CONFIG,\n    "nq_robust": NQ_ROBUST_CONFIG,\n}\n'
_SOURCES['tw_backdraw/levels.py'] = '"""由「前高 P」與「谷底 T」推導出的關鍵價位。\n\n台股當前實例：P = 47742、T = 39933、跌幅 R = 7809 點\n    主防線 (50%)  = 43837   ← 貼文的 43800\n    警戒線 (38.2%) = 42916\n    失效線        = 39933\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\n\nfrom .config import LevelConfig\n\n\n@dataclass(frozen=True)\nclass Levels:\n    peak: float\n    trough: float\n    half_line: float\n    half_line_with_buffer: float\n    warn_line: float\n    invalidation: float\n\n    @property\n    def drop(self) -> float:\n        return self.peak - self.trough\n\n    @property\n    def drop_pct(self) -> float:\n        return self.drop / self.peak\n\n    @property\n    def stop_line(self) -> float:\n        """真正會觸發出場的價位。\n\n        `zone()` 要落到 warning 得同時跌破警戒線**與**主防線的假跌破緩衝區，\n        所以實際的停損線是兩者取低。預設參數下警戒線與主防線重合\n        （`warn_line_ratio == half_line_ratio`），緩衝區就成了真正的觸發點 ——\n        收盤跌破主防線 0.5% 以內會被容忍，超過才出場。\n        """\n        return min(self.warn_line, self.half_line_with_buffer)\n\n    def repair_fraction(self, price: float) -> float:\n        """價格相當於補回跌幅的幾成。"""\n        if self.drop <= 0:\n            return 0.0\n        return (price - self.trough) / self.drop\n\n    def zone(self, price: float) -> str:\n        """把價格歸類到操作分區。"""\n        if price >= self.peak:\n            return "breakout"       # 已創高：轉移動停利\n        if price >= self.half_line:\n            return "healthy"        # 劇本正常：回檔即加碼\n        if price >= self.half_line_with_buffer:\n            return "buffer"         # 假跌破容忍區：不加碼、不減碼\n        if price >= self.warn_line:\n            return "caution"        # 跌破主防線：停止加碼\n        if price >= self.invalidation:\n            return "warning"        # 跌破 38.2%：減碼\n        return "invalidated"        # 跌破谷底：另一個故事，全出\n\n\ndef build_levels(peak: float, trough: float, cfg: LevelConfig) -> Levels:\n    if peak <= trough:\n        raise ValueError("前高必須高於谷底")\n    drop = peak - trough\n    half = trough + cfg.half_line_ratio * drop\n    return Levels(\n        peak=peak,\n        trough=trough,\n        half_line=half,\n        half_line_with_buffer=half * (1 - cfg.half_line_buffer),\n        warn_line=trough + cfg.warn_line_ratio * drop,\n        invalidation=trough,\n    )\n'
_SOURCES['tw_backdraw/setup.py'] = '"""辨識「快速修復」劇本。\n\n流程（全部以收盤價、可即時判定，不使用未來資料）：\n    1. 從滾動高點 P 起算，收盤跌破 P×(1-10%) → 進入回檔追蹤\n    2. 追蹤期間持續更新谷底 T（創更低就更新，計時歸零）\n    3. 自 T 起 N 個交易日內，收盤補回跌幅 ≥ 75% → 觸發訊號\n       （N ≤ 15 對應貼文中「89% 會先回到舊高點」的那一組）\n    4. 超過 15 日才補回 → 這一段作廢（那一組成功率只剩 48%，跟丟銅板一樣），\n       參考高點改錨到谷底之後的波段高，重新開始找下一組 P/T\n\n第 4 步的改錨很關鍵。少了它，參考高點會一直釘在舊高直到指數重新站上為止 ——\n台股 2000 年頭部之後花了 17.3 年才收復 10,202，中間包含 2008、2015、2020\n在內的所有回檔修復都會被那個舊高遮蔽，偵測器等於瞎掉。\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom datetime import date\n\nfrom .bars import Bar\nfrom .config import SetupConfig\n\n\n@dataclass(frozen=True)\nclass Episode:\n    """一段 ≥10% 的回檔，以及它為什麼（沒）觸發訊號。"""\n\n    peak: float\n    peak_date: date\n    peak_index: int\n    trough: float\n    trough_date: date\n    trough_index: int\n    lower_lows: int              # 追蹤期間破底幾次（每次都讓計時歸零）\n    best_in_window: float        # 15 日視窗內補回的最高比例\n    best_in_window_bars: int     # 上述最佳值出現在谷底後第幾日\n    fired: bool\n    end_index: int\n    end_date: date\n\n    @property\n    def drop_pct(self) -> float:\n        return (self.trough - self.peak) / self.peak\n\n    def reason(self, cfg: SetupConfig) -> str:\n        if self.fired:\n            return f"✅ {self.best_in_window_bars} 日補回 {self.best_in_window:.0%}"\n        return (f"❌ {cfg.max_repair_bars} 日內只補回 {self.best_in_window:.0%}"\n                f"（第 {self.best_in_window_bars} 日最佳）")\n\n\n@dataclass(frozen=True)\nclass FastRepairSetup:\n    peak: float\n    peak_date: date\n    trough: float\n    trough_date: date\n    trough_index: int\n    trigger_index: int\n    trigger_date: date\n    trigger_close: float\n    bars_to_repair: int\n    repair_fraction: float\n\n    @property\n    def drop_pct(self) -> float:\n        return (self.peak - self.trough) / self.peak\n\n    def describe(self) -> str:\n        return (\n            f"{self.trough_date} 谷底 {self.trough:,.0f}（自 {self.peak_date} 高點 "\n            f"{self.peak:,.0f} 回檔 {self.drop_pct:.1%}），"\n            f"{self.bars_to_repair} 個交易日補回 {self.repair_fraction:.0%}，"\n            f"{self.trigger_date} 觸發訊號 @ {self.trigger_close:,.0f}"\n        )\n\n\n@dataclass(frozen=True)\nclass LiveState:\n    """偵測器跑到最後一根 K 的當下狀態 —— 每日訊號報告用。\n\n    直接從 `scan_episodes()` 的同一個迴圈取得，不另外實作一份，\n    所以盤中看到的「還差多少觸發」與回測的判定必然一致。\n    """\n\n    state: str                   # normal / drawdown / expired / engaged\n    peak: float\n    peak_date: date\n    trough: float | None         # 只有 drawdown 狀態才有\n    trough_date: date | None\n    bars_since_trough: int | None\n    repair_fraction: float | None    # 目前補回幾成\n    best_in_window: float | None     # 視窗內補回過的最高比例\n    lower_lows: int\n    bars_left: int | None            # 修復視窗還剩幾個交易日\n\n    @property\n    def drop_pct(self) -> float | None:\n        if self.trough is None or self.peak <= 0:\n            return None\n        return (self.peak - self.trough) / self.peak\n\n    def trigger_close(self, cfg: SetupConfig) -> float | None:\n        """再收在多少以上就會觸發訊號。"""\n        if self.state != "drawdown" or self.trough is None:\n            return None\n        return self.trough + cfg.repair_fraction * (self.peak - self.trough)\n\n\ndef scan_episodes(bars: list[Bar], cfg: SetupConfig,\n                  live: list | None = None) -> list[Episode]:\n    """列出所有 ≥ `min_drawdown` 的回檔段落，含觸發與未觸發的原因。\n\n    `detect_setups()` 就是取這裡面 `fired=True` 的那些，所以兩者不會不一致。\n\n    傳入 `live=[]` 時，會把跑到最後一根 K 的 `LiveState` 追加進去 ——\n    每日訊號報告靠這個取得「目前追蹤到哪、還差多少觸發」，\n    而不是另外複製一份狀態機。\n    """\n    episodes: list[Episode] = []\n    if not bars:\n        return episodes\n\n    peak, peak_i = bars[0].close, 0\n    trough, trough_i = bars[0].close, 0\n    state = "normal"\n    lower_lows = 0\n    win_best, win_best_n = 0.0, 0\n\n    def flush(i: int, fired: bool) -> None:\n        episodes.append(Episode(\n            peak=peak, peak_date=bars[peak_i].d, peak_index=peak_i,\n            trough=trough, trough_date=bars[trough_i].d, trough_index=trough_i,\n            lower_lows=lower_lows, best_in_window=win_best,\n            best_in_window_bars=win_best_n, fired=fired,\n            end_index=i, end_date=bars[i].d,\n        ))\n\n    for i, bar in enumerate(bars):\n        c = bar.close\n\n        if state == "normal":\n            if c > peak:\n                peak, peak_i = c, i\n            elif c <= peak * (1 - cfg.min_drawdown):\n                state = "drawdown"\n                trough, trough_i = c, i\n                lower_lows, win_best, win_best_n = 0, 0.0, 0\n            continue\n\n        if state == "drawdown":\n            if c < trough:\n                # 創更低點：谷底、計時與視窗內最佳進度一起重設\n                trough, trough_i = c, i\n                lower_lows += 1\n                win_best, win_best_n = 0.0, 0\n                continue\n\n            elapsed = i - trough_i\n            frac = (c - trough) / (peak - trough) if peak > trough else 0.0\n            if elapsed <= cfg.max_repair_bars and frac > win_best:\n                win_best, win_best_n = frac, elapsed\n\n            if frac >= cfg.repair_fraction and elapsed <= cfg.max_repair_bars:\n                flush(i, fired=True)\n                state = "engaged"\n                continue\n\n            if elapsed > cfg.max_repair_bars:\n                # 修復視窗到期，這一段作廢\n                flush(i, fired=False)\n                if cfg.reanchor_on_expiry:\n                    seg = bars[trough_i:i + 1]\n                    k = max(range(len(seg)), key=lambda j: seg[j].close)\n                    peak, peak_i = seg[k].close, trough_i + k\n                    state = "normal"\n                    continue\n                # 不改錨：等指數重新站上舊高才解除\n                state = "expired"\n                continue\n\n            if c > peak:\n                flush(i, fired=False)\n                state, peak, peak_i = "normal", c, i\n            continue\n\n        if state == "expired":\n            if c > peak:\n                state, peak, peak_i = "normal", c, i\n            continue\n\n        if state == "engaged":\n            last = episodes[-1]\n            if (c > peak or c < last.trough\n                    or (i - last.end_index) > cfg.setup_expiry_bars):\n                state = "normal"\n                if c > peak:\n                    peak, peak_i = c, i\n            continue\n\n    if live is not None and bars:\n        i = len(bars) - 1\n        if state == "drawdown":\n            elapsed = i - trough_i\n            drop = peak - trough\n            live.append(LiveState(\n                state=state, peak=peak, peak_date=bars[peak_i].d,\n                trough=trough, trough_date=bars[trough_i].d,\n                bars_since_trough=elapsed,\n                repair_fraction=(bars[i].close - trough) / drop if drop > 0 else 0.0,\n                best_in_window=win_best, lower_lows=lower_lows,\n                bars_left=max(cfg.max_repair_bars - elapsed, 0)))\n        else:\n            live.append(LiveState(\n                state=state, peak=peak, peak_date=bars[peak_i].d,\n                trough=None, trough_date=None, bars_since_trough=None,\n                repair_fraction=None, best_in_window=None,\n                lower_lows=0, bars_left=None))\n\n    return episodes\n\n\ndef detect_setups(bars: list[Bar], cfg: SetupConfig) -> list[FastRepairSetup]:\n    """掃描整段歷史，回傳所有觸發過的快速修復訊號。"""\n    return [\n        FastRepairSetup(\n            peak=e.peak, peak_date=e.peak_date,\n            trough=e.trough, trough_date=e.trough_date, trough_index=e.trough_index,\n            trigger_index=e.end_index, trigger_date=e.end_date,\n            trigger_close=bars[e.end_index].close,\n            bars_to_repair=e.best_in_window_bars,\n            repair_fraction=e.best_in_window,\n        )\n        for e in scan_episodes(bars, cfg) if e.fired\n    ]\n'
_SOURCES['tw_backdraw/leveraged.py'] = '"""台灣50正2（00631L）的價格模型。\n\n實務上訊號來自加權指數，執行卻在槓桿 ETF 上，兩者不是同一條線：\n\n* 00631L 追蹤的是「台灣50指數單日報酬 2 倍」，不是加權指數，\n  但兩者日報酬相關性長期在 0.95 以上，訊號層面可互用。\n* 2 倍是「單日」複製，路徑相依：盤整盤會有波動耗損，\n  單邊上漲則會優於 2 倍。\n* 內扣（管理費 + 期貨轉倉/避險）約年化 1%～1.5%，逐日侵蝕淨值。\n\n沒有實際 00631L 日線時，用本模組由指數日報酬合成一條可回測的淨值路徑；\n有實際日線就直接餵真實價格，模型只用來做對照。\n"""\n\nfrom __future__ import annotations\n\nfrom .bars import Bar\nfrom .config import CostConfig\n\n\ndef synth_leveraged_path(\n    bars: list[Bar],\n    cost: CostConfig,\n    leverage: float = 2.0,\n    start_price: float = 100.0,\n) -> list[float]:\n    """由指數日線合成 2 倍槓桿 ETF 的收盤淨值序列。"""\n    path = [start_price]\n    for prev, cur in zip(bars, bars[1:]):\n        r = cur.close / prev.close - 1.0\n        nav = path[-1] * (1.0 + leverage * r - cost.daily_carry)\n        # 槓桿 ETF 淨值不會歸零/轉負，但單日 -50% 指數已超出任何現實情境；\n        # 保底避免回測數值爆掉。\n        path.append(max(nav, 1e-6))\n    return path\n\n\ndef decay_estimate(index_return: float, realized_vol: float, days: int, cost: CostConfig,\n                   leverage: float = 2.0) -> float:\n    """粗估持有 N 日後，槓桿 ETF 相對「指數報酬 × 2」的落差。\n\n    近似式: 2x 報酬 ≈ L·r - 0.5·L·(L-1)·σ²·(days/252) - carry·days/252\n    用來提醒：這個劇本必須是「快速、單邊」的行情才值得用槓桿工具。\n    """\n    variance_drag = 0.5 * leverage * (leverage - 1.0) * (realized_vol ** 2) * (days / cost.trading_days)\n    carry_drag = cost.daily_carry * days\n    return leverage * index_return - variance_drag - carry_drag\n'
_SOURCES['tw_backdraw/engine.py'] = '"""策略執行引擎（狀態機）。\n\n判斷一律用收盤價，成交一律落在下一個交易日，\n避免「當日收盤發訊號、當日收盤成交」這種實務上做不到的假設。\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom datetime import date\n\nfrom .bars import Bar\nfrom .config import DEFAULT_CONFIG, StrategyConfig\nfrom .levels import Levels, build_levels\nfrom .setup import FastRepairSetup, detect_setups\n\n\n@dataclass\nclass Fill:\n    d: date\n    side: str            # buy / sell\n    reason: str\n    index_price: float\n    etf_price: float\n    weight: float        # 買：佔訊號日權益比例；賣：佔當時持股比例\n    units: float\n    cash_flow: float\n\n    def describe(self) -> str:\n        verb = "買進" if self.side == "buy" else "賣出"\n        return (f"{self.d} {verb} {self.weight:>6.1%} @ ETF {self.etf_price:,.2f} "\n                f"(指數 {self.index_price:,.0f})  {self.reason}")\n\n\n@dataclass\nclass Trade:\n    setup: FastRepairSetup\n    levels: Levels\n    target_weight: float\n    fills: list[Fill] = field(default_factory=list)\n    entry_date: date | None = None\n    exit_date: date | None = None\n    exit_reason: str = "open"\n    equity_at_entry: float = 1.0\n    equity_at_exit: float = 1.0\n    max_adverse_index: float = 0.0   # 進場後指數最大不利波動\n    reached_prior_high: bool = False\n    swing_high: float = 0.0          # 訊號後的最高收盤（回檔梯的基準）\n    pending_ladder: list[tuple[float, float]] = field(default_factory=list)  # 尚未成交的加碼梯\n    bars_held: int = 0\n\n    @property\n    def ret(self) -> float:\n        return self.equity_at_exit / self.equity_at_entry - 1.0\n\n    @property\n    def filled_weight(self) -> float:\n        return sum(f.weight for f in self.fills if f.side == "buy")\n\n\n@dataclass\nclass Result:\n    trades: list[Trade]\n    equity_curve: list[tuple[date, float]]\n    setups: list[FastRepairSetup]\n\n    @property\n    def final_equity(self) -> float:\n        return self.equity_curve[-1][1] if self.equity_curve else 1.0\n\n\ndef _blended_stop_distance(entry_index: float, levels: Levels, cfg: StrategyConfig) -> float:\n    """兩段式停損的預期虧損距離（指數口徑）。\n\n    先在警戒線減碼一半，剩下的在谷底出清，真正的預期損失介於兩者之間。\n    警戒段用 `levels.stop_line`（含主防線的假跌破緩衝）—— 那才是真正會成交的價位。\n    """\n    to_warn = max(entry_index - levels.stop_line, 0.0) / entry_index\n    to_trough = max(entry_index - levels.invalidation, 0.0) / entry_index\n    f = cfg.exit.warn_derisk_fraction\n    blended = f * to_warn + (1.0 - f) * to_trough\n    return max(blended, cfg.sizing.min_stop_distance)\n\n\ndef position_size(entry_index: float, levels: Levels, cfg: StrategyConfig) -> float:\n    """這一筆交易的目標持股水位（佔權益比例）。\n\n    槓桿 ETF 的虧損 ≈ 指數跌幅 × 2，所以指數停損距離越遠、部位必須越小。\n    """\n    expected_loss = cfg.sizing.leverage * _blended_stop_distance(entry_index, levels, cfg)\n    return min(cfg.sizing.max_weight, cfg.sizing.risk_per_trade / expected_loss)\n\n\ndef moving_average(bars: list[Bar], period: int) -> list[float | None]:\n    """加權指數收盤的簡單移動平均；資料不足時為 None。"""\n    out: list[float | None] = []\n    total = 0.0\n    for i, b in enumerate(bars):\n        total += b.close\n        if i >= period:\n            total -= bars[i - period].close\n        out.append(total / period if i >= period - 1 else None)\n    return out\n\n\ndef breakout_stop(cfg: StrategyConfig, prior_high: float, peak_since_breakout: float,\n                  ma: float | None) -> tuple[float, str]:\n    """創高之後的出場線，回傳 (價位, 說明)。"""\n    mode = cfg.exit.exit_mode\n    trail = peak_since_breakout * (1 - cfg.exit.trail_drawdown)\n\n    if mode == "trail":\n        return trail, f"移動停利：自 {peak_since_breakout:,.0f} 回檔 {cfg.exit.trail_drawdown:.0%}"\n\n    # 均線棘輪：先以前高為出場線，等 MA 爬過前高才改看 MA\n    if ma is None or ma <= prior_high:\n        ratchet, why = prior_high, f"跌破前高 {prior_high:,.0f}（MA{cfg.exit.ma_period} 尚未站上）"\n    else:\n        ratchet, why = ma, f"跌破 MA{cfg.exit.ma_period} {ma:,.0f}"\n\n    if mode == "ma_ratchet":\n        return ratchet, why\n    if mode == "both":\n        return ((trail, f"移動停利：自 {peak_since_breakout:,.0f} 回檔 {cfg.exit.trail_drawdown:.0%}")\n                if trail > ratchet else (ratchet, why))\n    raise ValueError(f"未知的 exit_mode: {mode!r}")\n\n\ndef ladder_weights(cfg: StrategyConfig, target: float) -> list[tuple[float, float]]:\n    """回檔加碼梯的實際權重。\n\n    底倉與加碼梯合計必須剛好等於目標水位：加碼梯的設定值是「彼此之間的比例」，\n    實際可用的額度是 1 − base_weight。少了這一步，base_weight=1.0 會在滿倉之後\n    再加 60%，把部位推到目標的 160%，直接突破風險預算。\n    """\n    remaining = max(0.0, 1.0 - cfg.entry.base_weight)\n    total = sum(w for _, w in cfg.entry.pullback_ladder)\n    if remaining <= 0 or total <= 0:\n        return []\n    return [(thr, w / total * remaining * target) for thr, w in cfg.entry.pullback_ladder]\n\n\ndef _risk_scale(entry_index: float, fill_index: float, levels: Levels,\n                cfg: StrategyConfig) -> float:\n    """往上加碼時的權重縮放。\n\n    部位大小是在訊號日算好的；若之後在更高的價位補倉，同樣的股數要承擔更長的\n    停損距離，實際風險就會超出預算。這裡按停損距離等比縮小，並限制在 1.0 以內\n    ——只會因為買貴而縮手，不會因為買便宜而放大部位。\n    """\n    base = _blended_stop_distance(entry_index, levels, cfg)\n    now = _blended_stop_distance(fill_index, levels, cfg)\n    return min(1.0, base / now) if now > 0 else 1.0\n\n\nclass Engine:\n    """單一部位、單一標的（台灣50正2）的回測 / 實盤訊號引擎。"""\n\n    def __init__(self, cfg: StrategyConfig | None = None):\n        self.cfg = cfg or DEFAULT_CONFIG\n\n    def run(self, bars: list[Bar], etf_prices: list[float]) -> Result:\n        cfg = self.cfg\n        if len(bars) != len(etf_prices):\n            raise ValueError("指數日線與 ETF 價格長度不一致")\n\n        setups = detect_setups(bars, cfg.setup)\n        by_trigger = {s.trigger_index: s for s in setups}\n        mas = (moving_average(bars, cfg.exit.ma_period)\n               if cfg.exit.exit_mode in ("ma_ratchet", "both") else [None] * len(bars))\n\n        cash, units = 1.0, 0.0\n        equity_curve: list[tuple[date, float]] = []\n        trades: list[Trade] = []\n\n        trade: Trade | None = None\n        pending: list[tuple[str, float, str]] = []   # (side, weight, reason)\n        base_equity = 1.0\n        swing_high = 0.0\n        peak_since_breakout = 0.0\n        unfilled: list[tuple[float, float]] = []\n        derisked = reloaded = took_profit = False\n\n        for i, bar in enumerate(bars):\n            px = etf_prices[i]\n\n            # ---- 1. 執行前一交易日收盤掛出的委託 ----\n            for side, weight, reason in pending:\n                if side == "buy":\n                    notional = weight * base_equity\n                    if notional <= 0:\n                        continue\n                    fee = notional * cfg.cost.buy_cost\n                    u = notional / px\n                    cash -= notional + fee\n                    units += u\n                    assert trade is not None\n                    trade.fills.append(\n                        Fill(bar.d, "buy", reason, bar.close, px, weight, u, -(notional + fee))\n                    )\n                    if trade.entry_date is None:\n                        trade.entry_date = bar.d\n                        trade.equity_at_entry = base_equity\n                else:\n                    u = units * weight\n                    if u <= 0:\n                        continue\n                    proceeds = u * px * (1 - cfg.cost.sell_cost)\n                    cash += proceeds\n                    units -= u\n                    assert trade is not None\n                    trade.fills.append(\n                        Fill(bar.d, "sell", reason, bar.close, px, weight, u, proceeds)\n                    )\n            pending = []\n            equity = cash + units * px\n\n            # ---- 2. 收盤後評估，掛出明日委託 ----\n            if trade is None:\n                setup = by_trigger.get(i)\n                if setup is not None:\n                    levels = build_levels(setup.peak, setup.trough, cfg.levels)\n                    target = position_size(bar.close, levels, cfg)\n                    trade = Trade(setup=setup, levels=levels, target_weight=target,\n                                  equity_at_entry=equity)\n                    base_equity = equity\n                    swing_high = bar.close\n                    peak_since_breakout = 0.0\n                    derisked = reloaded = took_profit = False\n                    unfilled = ladder_weights(cfg, target)\n                    pending.append(("buy", cfg.entry.base_weight * target, "底倉：訊號確認，不等回檔"))\n            else:\n                lv, c = trade.levels, bar.close\n                swing_high = max(swing_high, c)\n                bars_since = i - trade.setup.trigger_index\n                trade.swing_high = swing_high\n                trade.bars_held = bars_since\n                if trade.fills:\n                    trade.max_adverse_index = min(\n                        trade.max_adverse_index, c / trade.fills[0].index_price - 1.0\n                    )\n                zone = lv.zone(c)\n\n                if zone == "invalidated" and cfg.exit.hard_stop_at_trough:\n                    unfilled = []\n                    pending.append(("sell", 1.0, f"劇本失效：收盤跌破谷底 {lv.invalidation:,.0f}"))\n                    trade.exit_reason = "stop_trough"\n\n                elif zone == "warning" and not derisked:\n                    unfilled = []\n                    derisked = True\n                    verb = "清倉" if cfg.exit.warn_derisk_fraction >= 1.0 else "減碼"\n                    why = (f"{cfg.levels.warn_line_ratio:.1%} 回補位"\n                           if lv.stop_line >= lv.warn_line\n                           else f"主防線 {lv.half_line:,.0f} 的 "\n                                f"{cfg.levels.half_line_buffer:.1%} 緩衝")\n                    pending.append(("sell", cfg.exit.warn_derisk_fraction,\n                                    f"警戒{verb}：收盤跌破 {lv.stop_line:,.0f}（{why}）"))\n\n                else:\n                    adds_allowed = zone in ("healthy", "buffer", "breakout")\n\n                    if c >= lv.peak:\n                        trade.reached_prior_high = True\n                        peak_since_breakout = max(peak_since_breakout, c)\n\n                    # (a) 突破前高 → 依設定補齊或取消未成交的分批單\n                    breakout_filled = False\n                    if trade.reached_prior_high and unfilled:\n                        if cfg.entry.breakout_fills_remainder and adds_allowed:\n                            scale = _risk_scale(trade.setup.trigger_close, c, lv, cfg)\n                            for _, w in unfilled:\n                                pending.append(("buy", w * scale,\n                                                f"突破補齊：站上前高 {lv.peak:,.0f}"\n                                                f"（風險縮放 {scale:.0%}）"))\n                            breakout_filled = True\n                        unfilled = []\n\n                    # (b) 回到前高：可選的分批落袋（預設 0，前高不是賣出的理由）\n                    if (trade.reached_prior_high and not took_profit and units > 0\n                            and not breakout_filled and cfg.exit.target_take_fraction > 0):\n                        took_profit = True\n                        pending.append(("sell", cfg.exit.target_take_fraction,\n                                        f"目標達陣：回到前高 {lv.peak:,.0f}"))\n\n                    # (c) 創高之後，出場全部交給停利機制\n                    if trade.reached_prior_high and units > 0:\n                        stop, why = breakout_stop(cfg, lv.peak, peak_since_breakout, mas[i])\n                        if c < stop:\n                            pending.append(("sell", 1.0, why))\n                            trade.exit_reason = "trail"\n\n                    # (d) 減碼後收復主防線 → 補回一次\n                    if derisked and not reloaded and adds_allowed and c >= lv.half_line and units > 0:\n                        reloaded = True\n                        # 解除減碼旗標：回補之後若再度跌破警戒線，還要能再減一次\n                        derisked = False\n                        pending.append(("buy", trade.filled_weight * cfg.exit.warn_derisk_fraction,\n                                        f"回補：收復主防線 {lv.half_line:,.0f}"))\n\n                    # (e) 回檔加碼梯\n                    if unfilled and adds_allowed:\n                        pullback = c / swing_high - 1.0\n                        still: list[tuple[float, float]] = []\n                        for thr, w in unfilled:\n                            if pullback <= -thr:\n                                pending.append(("buy", w, f"回檔加碼：自波段高點 {pullback:.1%}"))\n                            else:\n                                still.append((thr, w))\n                        unfilled = still\n\n                    # (f) 時間補齊：等不到回檔，不參與才是最大的風險\n                    if unfilled and adds_allowed and bars_since >= cfg.entry.fill_timeout_bars:\n                        scale = _risk_scale(trade.setup.trigger_close, c, lv, cfg)\n                        for _, w in unfilled:\n                            pending.append(("buy", w * scale,\n                                            f"時間補齊：{bars_since} 個交易日未見回檔"\n                                            f"（風險縮放 {scale:.0%}）"))\n                        unfilled = []\n\n                    # (g) 劇本過期\n                    if (not trade.reached_prior_high and units > 0\n                            and bars_since >= cfg.setup.setup_expiry_bars):\n                        unfilled = []\n                        pending.append(("sell", 1.0, f"劇本過期：{bars_since} 個交易日未創高"))\n                        trade.exit_reason = "expired"\n\n                trade.pending_ladder = list(unfilled)\n\n                # 部位歸零且沒有待買單 → 結案\n                if units <= 0 and trade.entry_date is not None and not any(\n                        s == "buy" for s, _, _ in pending):\n                    if trade.exit_reason == "open":\n                        trade.exit_reason = "flat"\n                    trade.exit_date = bar.d\n                    trade.equity_at_exit = equity\n                    trades.append(trade)\n                    trade = None\n\n            equity_curve.append((bar.d, cash + units * px))\n\n        if trade is not None:\n            trade.exit_date = bars[-1].d\n            trade.equity_at_exit = cash + units * etf_prices[-1]\n            trades.append(trade)\n\n        return Result(trades=trades, equity_curve=equity_curve, setups=setups)\n'
_SOURCES['tw_backdraw/backtest.py'] = '"""回測與績效統計。"""\n\nfrom __future__ import annotations\n\nimport statistics\nfrom dataclasses import dataclass\n\nfrom .bars import Bar\nfrom .config import DEFAULT_CONFIG, StrategyConfig\nfrom .engine import Engine, Result\nfrom .leveraged import synth_leveraged_path\n\n\n@dataclass(frozen=True)\nclass Stats:\n    n_setups: int\n    n_trades: int\n    hit_prior_high: int\n    hit_rate: float\n    win_rate: float\n    avg_return: float\n    median_return: float\n    best: float\n    worst: float\n    total_return: float\n    max_drawdown: float\n    median_max_adverse: float\n\n    def render(self) -> str:\n        return "\\n".join([\n            f"訊號次數            {self.n_setups}",\n            f"實際交易            {self.n_trades}",\n            f"回到前高            {self.hit_prior_high} ({self.hit_rate:.0%})",\n            f"獲利比例            {self.win_rate:.0%}",\n            f"單筆平均報酬        {self.avg_return:+.1%}",\n            f"單筆中位數報酬      {self.median_return:+.1%}",\n            f"最佳 / 最差         {self.best:+.1%} / {self.worst:+.1%}",\n            f"權益總報酬          {self.total_return:+.1%}",\n            f"權益最大回檔        {self.max_drawdown:.1%}",\n            f"進場後指數最大逆行  {self.median_max_adverse:.1%}（中位數）",\n        ])\n\n\ndef align_etf(bars: list[Bar], etf_bars: list[Bar]) -> tuple[list[Bar], list[float]]:\n    """把 ETF 日線對齊到指數日線，只保留兩邊都有交易的日子。\n\n    00631L 2014-10-31 才掛牌，比加權指數短很多；用真實 ETF 價格回測時，\n    回測期間會自動縮到重疊區間，而不是拿合成價去補前面那一段。\n    """\n    etf_by_date = {b.d: b.close for b in etf_bars}\n    kept = [(b, etf_by_date[b.d]) for b in bars if b.d in etf_by_date]\n    if not kept:\n        raise ValueError("指數與 ETF 日線沒有重疊的交易日")\n    return [b for b, _ in kept], [p for _, p in kept]\n\n\ndef run_backtest(bars: list[Bar], cfg: StrategyConfig | None = None,\n                 etf_prices: list[float] | None = None) -> tuple[Result, Stats]:\n    cfg = cfg or DEFAULT_CONFIG\n    if etf_prices is None:\n        etf_prices = synth_leveraged_path(bars, cfg.cost, cfg.sizing.leverage)\n    result = Engine(cfg).run(bars, etf_prices)\n    return result, summarize(result)\n\n\ndef summarize(result: Result) -> Stats:\n    rets = [t.ret for t in result.trades]\n    hits = sum(1 for t in result.trades if t.reached_prior_high)\n    adverse = [t.max_adverse_index for t in result.trades] or [0.0]\n\n    peak = -1e18\n    max_dd = 0.0\n    for _, eq in result.equity_curve:\n        peak = max(peak, eq)\n        max_dd = min(max_dd, eq / peak - 1.0)\n\n    n = len(result.trades)\n    return Stats(\n        n_setups=len(result.setups),\n        n_trades=n,\n        hit_prior_high=hits,\n        hit_rate=hits / n if n else 0.0,\n        win_rate=sum(1 for r in rets if r > 0) / n if n else 0.0,\n        avg_return=statistics.fmean(rets) if rets else 0.0,\n        median_return=statistics.median(rets) if rets else 0.0,\n        best=max(rets) if rets else 0.0,\n        worst=min(rets) if rets else 0.0,\n        total_return=result.final_equity - 1.0,\n        max_drawdown=max_dd,\n        median_max_adverse=statistics.median(adverse),\n    )\n\n\n@dataclass(frozen=True)\nclass TradeReview:\n    """單筆 ETF 交易的完整檢視：報酬、期間極值，以及當初的進場條件。"""\n\n    trade: "object"          # engine.Trade\n    bars_held: int\n    weight: float            # 實際建立的部位水位（佔權益比例）\n    stop_distance: float     # 訊號日收盤到停損線的距離\n    mfe: float               # 期間最大浮動獲利（權益，相對進場）\n    mae: float               # 期間最大浮動虧損（權益，相對進場）\n    max_drawdown: float      # 期間內從波段高點起算的最大回撤\n\n    @property\n    def setup(self):\n        return self.trade.setup\n\n    @property\n    def levels(self):\n        return self.trade.levels\n\n    @property\n    def from_peak(self) -> float:\n        s = self.setup\n        return s.trigger_close / s.peak - 1.0\n\n    @property\n    def exit_reason(self) -> str:\n        t = self.trade\n        if t.exit_reason == "open":\n            return "尚未出場（持有中）"\n        fills = t.fills\n        if len(fills) > 1 and fills[-1].side == "sell":\n            return fills[-1].reason\n        return t.exit_reason\n\n\ndef review_trades(result: Result) -> list[TradeReview]:\n    """把權益曲線切成逐筆部位，算出每筆的 MFE / MAE / 期間最大回撤。\n\n    極值以**整體權益**衡量 —— 沒滿倉的時候現金部位會稀釋波動，\n    這正是實際帳戶看到的數字，不是標的本身的漲跌。\n    """\n    idx = {d: i for i, (d, _) in enumerate(result.equity_curve)}\n    out: list[TradeReview] = []\n    for t in result.trades:\n        if t.entry_date is None:\n            continue\n        a = idx[t.entry_date]\n        b = idx[t.exit_date] if t.exit_date in idx else len(result.equity_curve) - 1\n        seg = [eq for _, eq in result.equity_curve[a:b + 1]]\n        base = t.equity_at_entry\n        if not seg or base <= 0:\n            continue\n        peak, dd = seg[0], 0.0\n        for x in seg:\n            peak = max(peak, x)\n            dd = min(dd, x / peak - 1.0)\n        entry = t.setup.trigger_close\n        out.append(TradeReview(\n            trade=t, bars_held=b - a, weight=t.filled_weight,\n            stop_distance=max(entry - t.levels.stop_line, 0.0) / entry,\n            mfe=max(seg) / base - 1.0, mae=min(seg) / base - 1.0,\n            max_drawdown=dd))\n    return out\n'
_SOURCES['tw_backdraw/plan.py'] = '"""把訊號翻譯成可以直接下單的操作計畫。"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\n\nfrom .config import DEFAULT_CONFIG, StrategyConfig\nfrom .engine import ladder_weights, position_size\nfrom .levels import Levels, build_levels\n\n\n@dataclass(frozen=True)\nclass Order:\n    tag: str\n    weight: float          # 佔總權益比例\n    trigger: str\n    index_level: float | None   # 觸發時的指數概略位置（回檔梯以波段高點推算）\n\n\n@dataclass(frozen=True)\nclass TradePlan:\n    levels: Levels\n    reference_index: float\n    target_weight: float\n    orders: list[Order]\n    cfg: StrategyConfig\n    capital: float | None = None\n\n    def render(self) -> str:\n        lv = self.levels\n        out: list[str] = []\n        out.append("=" * 68)\n        out.append("台灣指數快速修復 → 台灣50正2(00631L) 回檔入場計畫")\n        out.append("=" * 68)\n        out.append("")\n        out.append(f"前波高點 P        {lv.peak:>10,.0f}   ← 主目標（歷史 89% 會回到這裡）")\n        out.append(f"波段谷底 T        {lv.trough:>10,.0f}   ← 失效線：收盤跌破 = 全部出場")\n        out.append(f"跌幅 R            {lv.drop:>10,.0f} 點 ({lv.drop_pct:.1%})")\n        out.append("")\n        ex, lc = self.cfg.exit, self.cfg.levels\n        derisk = "全部出場" if ex.warn_derisk_fraction >= 1.0 else f"減碼 {ex.warn_derisk_fraction:.0%}"\n        out.append("關鍵價位")\n        out.append(f"  61.8% 回補      {lv.trough + 0.618 * lv.drop:>10,.0f}")\n        if abs(lc.warn_line_ratio - lc.half_line_ratio) < 1e-9:\n            # 警戒線與主防線重合：只印一條，避免看起來像兩個不同的動作\n            out.append(f"  主防線 = 警戒線 {lv.half_line:>10,.0f}   "\n                       f"({lc.half_line_ratio:.1%} 回補位) 收盤跌破 → {derisk}")\n            out.append(f"  容忍緩衝 (-{lc.half_line_buffer:.1%}){lv.half_line_with_buffer:>8,.0f}   "\n                       f"假跌破區，不動作")\n        else:\n            out.append(f"  主防線 ({lc.half_line_ratio:.0%})    {lv.half_line:>10,.0f}   歷史回檔多數止步於此")\n            out.append(f"  容忍緩衝 (-{lc.half_line_buffer:.1%}){lv.half_line_with_buffer:>8,.0f}   "\n                       f"假跌破區，不加碼也不減碼")\n            out.append(f"  警戒線 ({lc.warn_line_ratio:.1%}) {lv.warn_line:>10,.0f}   收盤跌破 → {derisk}")\n        out.append(f"  失效線          {lv.invalidation:>10,.0f}   收盤跌破 → 清倉")\n        out.append("")\n        out.append(f"現價（參考）      {self.reference_index:>10,.0f}   "\n                   f"補回 {lv.repair_fraction(self.reference_index):.0%}，"\n                   f"距前高 {self.reference_index / lv.peak - 1:+.1%}，分區：{lv.zone(self.reference_index)}")\n        out.append("")\n        out.append(f"目標總持股水位    {self.target_weight:.0%} 的權益"\n                   + (f"（約 {self.capital * self.target_weight:,.0f} 元）" if self.capital else ""))\n        out.append("")\n        out.append("進場梯（權重為佔總權益比例）"\n                   if len(self.orders) > 1 else "進場（權重為佔總權益比例）")\n        for o in self.orders:\n            if o.weight > 0:\n                size = f"{o.weight:>6.1%}"\n                amount = f"  ≈ {self.capital * o.weight:,.0f} 元" if self.capital else ""\n            else:\n                size, amount = "  剩餘", ""\n            level = f"（指數約 {o.index_level:,.0f}）" if o.index_level else ""\n            out.append(f"  {o.tag:<10} {size}{amount:<18} {o.trigger}{level}")\n        out.append("")\n        out.append("出場")\n        if ex.target_take_fraction > 0:\n            out.append(f"  觸及 {lv.peak:,.0f}    → 賣出 {ex.target_take_fraction:.0%} 落袋，其餘轉停利")\n        else:\n            out.append(f"  觸及 {lv.peak:,.0f}    → 不賣（前高不是賣出的理由），啟動停利")\n        if ex.exit_mode == "trail":\n            out.append(f"  移動停利          自波段最高收盤回檔 {ex.trail_drawdown:.0%}（指數）→ 出清")\n        elif ex.exit_mode == "ma_ratchet":\n            out.append(f"  均線棘輪          出場線 = max(前高, MA{ex.ma_period})，跌破 → 出清")\n        else:\n            out.append(f"  停利（取較緊）    max(前高, MA{ex.ma_period}) 與 "\n                       f"自高點回檔 {ex.trail_drawdown:.0%} 兩者取高 → 跌破出清")\n        out.append(f"  收盤 < {lv.stop_line:,.0f}   → {derisk}")\n        out.append(f"  收盤 < {lv.invalidation:,.0f}   → 全部出場，不留倉")\n        out.append("")\n        out.append("提醒：00631L 為 2 倍槓桿，指數 -1% ≈ ETF -2%（另有波動耗損與內扣）。")\n        to_stop = lv.invalidation / self.reference_index - 1\n        to_warn = lv.stop_line / self.reference_index - 1\n        out.append(f"      現價到停損線 {to_warn:.1%}（ETF 約 {2 * to_warn:.0%}）、"\n                   f"到失效線 {to_stop:.1%}（ETF 約 {2 * to_stop:.0%}）。")\n        return "\\n".join(out)\n\n\ndef build_plan(peak: float, trough: float, reference_index: float,\n               cfg: StrategyConfig | None = None,\n               capital: float | None = None) -> TradePlan:\n    cfg = cfg or DEFAULT_CONFIG\n    lv = build_levels(peak, trough, cfg.levels)\n    target = position_size(reference_index, lv, cfg)\n\n    orders = [Order(tag="底倉", weight=cfg.entry.base_weight * target,\n                    trigger="訊號確認後次一交易日市價買進，不等回檔", index_level=None)]\n    for thr, w in ladder_weights(cfg, target):\n        orders.append(\n            Order(tag=f"回檔 -{thr:.0%}", weight=w,\n                  trigger=f"自訊號後波段最高收盤回檔 {thr:.0%} 且收盤仍在 {lv.half_line_with_buffer:,.0f} 之上",\n                  index_level=reference_index * (1 - thr))\n        )\n    if len(orders) > 1:      # 只有存在加碼梯時，時間補齊才有意義\n        orders.append(\n            Order(tag="時間補齊", weight=0.0,\n                  trigger=f"訊號後 {cfg.entry.fill_timeout_bars} 個交易日仍未觸發回檔梯 → 剩餘部位市價補齊",\n                  index_level=None)\n        )\n    return TradePlan(levels=lv, reference_index=reference_index, target_weight=target,\n                     orders=orders, cfg=cfg, capital=capital)\n'
_SOURCES['tw_backdraw/status.py'] = '"""目前這一輪劇本的即時狀態：手上該做什麼、下一個觸發點在哪。"""\n\nfrom __future__ import annotations\n\nfrom .bars import Bar\nfrom .config import StrategyConfig\nfrom .engine import Result, Trade\n\n\ndef render_status(result: Result, bars: list[Bar], cfg: StrategyConfig,\n                  capital: float | None = None) -> str:\n    last = bars[-1]\n    out: list[str] = ["=" * 72,\n                      f"部位現況（資料截至 {last.d}，指數收盤 {last.close:,.0f}）",\n                      "=" * 72, ""]\n\n    open_trades = [t for t in result.trades if t.exit_reason == "open"]\n    if not open_trades:\n        if result.setups:\n            s = result.setups[-1]\n            out.append("目前沒有進行中的部位。最近一次訊號：")\n            out.append(f"  {s.describe()}")\n            if result.trades:\n                t = result.trades[-1]\n                out.append(f"  該筆已於 {t.exit_date} 出場（{t.exit_reason}），報酬 {t.ret:+.1%}")\n        else:\n            out.append("目前沒有進行中的部位，資料期間內也沒有觸發過訊號。")\n        out.append("")\n        out.append("下一次進場條件：自高點回檔 ≥"\n                   f"{cfg.setup.min_drawdown:.0%} 後，谷底起 ≤{cfg.setup.max_repair_bars} 個交易日內"\n                   f"收盤補回 ≥{cfg.setup.repair_fraction:.0%}。")\n        return "\\n".join(out)\n\n    t = open_trades[-1]\n    lv = t.levels\n    c = last.close\n    zone = lv.zone(c)\n\n    out.append(f"訊號        {t.setup.describe()}")\n    out.append(f"已持有      {t.bars_held} 個交易日"\n               f"（劇本有效期 {cfg.setup.setup_expiry_bars} 日）")\n    out.append("")\n    out.append(f"目標水位    {t.target_weight:.1%}"\n               + (f"（約 {capital * t.target_weight:,.0f} 元）" if capital else ""))\n    out.append(f"已建立      {t.filled_weight:.1%}"\n               + (f"（約 {capital * t.filled_weight:,.0f} 元）" if capital else "")\n               + f"\u3000＝ 目標的 {t.filled_weight / t.target_weight:.0%}")\n    out.append("")\n    out.append("已成交")\n    for f in t.fills:\n        out.append("  " + f.describe())\n    out.append("")\n\n    zone_note = {\n        "breakout": "已站上前高 —— 出場交給移動停利",\n        "healthy": "劇本正常 —— 回檔就是加碼機會",\n        "buffer": "主防線假跌破容忍區 —— 不加碼、也不減碼",\n        "caution": "已跌破主防線 —— 停止加碼，只留現有部位",\n        "warning": "已跌破警戒線 —— 減碼一半",\n        "invalidated": "已跌破谷底 —— 劇本失效，清倉",\n    }[zone]\n    out.append(f"目前分區    {zone}\u3000{zone_note}")\n    out.append(f"距前高      {c / lv.peak - 1:+.1%}\u3000"\n               f"距主防線 {c / lv.half_line - 1:+.1%}\u3000"\n               f"距停損線 {c / lv.stop_line - 1:+.1%}\u3000"\n               f"距失效線 {c / lv.invalidation - 1:+.1%}")\n    out.append("")\n\n    out.append("下一步（收盤價判定，次一交易日執行）")\n    if t.pending_ladder:\n        for thr, w in t.pending_ladder:\n            trigger_px = t.swing_high * (1 - thr)\n            gap = trigger_px / c - 1\n            blocked = trigger_px < lv.half_line_with_buffer\n            note = "\u3000⚠ 觸發價已低於假跌破緩衝線，屆時不執行" if blocked else ""\n            amount = f"（約 {capital * w:,.0f} 元）" if capital else ""\n            out.append(f"  買 {w:>6.1%}{amount}\u3000收盤 ≤ {trigger_px:,.0f}"\n                       f"（自波段高 {t.swing_high:,.0f} 回檔 {thr:.0%}，距現價 {gap:+.1%}）{note}")\n        remaining = cfg.entry.fill_timeout_bars - t.bars_held\n        if remaining > 0:\n            out.append(f"  買 {\'剩餘\':>6}\u3000再過 {remaining} 個交易日仍未觸發回檔梯 → 市價補齊")\n        else:\n            out.append(f"  買 {\'剩餘\':>6}\u3000已過時間門檻 → 次一交易日市價補齊")\n        if cfg.entry.breakout_fills_remainder:\n            out.append(f"  買 {\'剩餘\':>6}\u3000收盤 > {lv.peak:,.0f}（前高）→ 補齊，權重按停損距離縮放")\n    else:\n        out.append("  加碼梯已全部處理，不再加碼")\n\n    if cfg.exit.target_take_fraction > 0:\n        out.append(f"  賣 {cfg.exit.target_take_fraction:>6.0%}\u3000收盤 ≥ {lv.peak:,.0f}（前高）")\n    if t.reached_prior_high:\n        out.append(f"  賣 {\'全部\':>6}\u3000自波段最高收盤回檔 {cfg.exit.trail_drawdown:.0%}（移動停利已啟動）")\n    else:\n        out.append(f"  賣 {\'全部\':>6}\u3000創高後啟動移動停利（自最高收盤回檔 {cfg.exit.trail_drawdown:.0%}）")\n    note = ("警戒線" if lv.stop_line >= lv.warn_line\n            else f"主防線 {lv.half_line:,.0f} 的 {cfg.levels.half_line_buffer:.1%} 緩衝")\n    out.append(f"  賣 {cfg.exit.warn_derisk_fraction:>6.0%}\u3000收盤 < {lv.stop_line:,.0f}（{note}）")\n    out.append(f"  賣 {\'全部\':>6}\u3000收盤 < {lv.invalidation:,.0f}（失效線）")\n    out.append("")\n\n    # 實際會把部位清光的第一條線：警戒線設定為全數出場時就是它，否則才是失效線\n    full_exit = (lv.stop_line if cfg.exit.warn_derisk_fraction >= 1.0 else lv.invalidation)\n    lev = cfg.sizing.leverage\n    gap = full_exit / c - 1\n    out.append(f"預期最大損失  跌到出清線 {full_exit:,.0f}（{gap:.1%}），"\n               f"00631L 約 {lev * gap:.0%}；依已建立的 {t.filled_weight:.1%} 部位，"\n               f"權益衝擊約 {t.filled_weight * lev * gap:.1%}")\n    if full_exit != lv.invalidation:\n        gap2 = lv.invalidation / c - 1\n        out.append(f"              （跳空直接摜破失效線 {lv.invalidation:,.0f} 的極端情形："\n                   f"{gap2:.1%}，權益衝擊約 {t.filled_weight * lev * gap2:.1%}）")\n    return "\\n".join(out)\n\n\ndef open_trade(result: Result) -> Trade | None:\n    for t in reversed(result.trades):\n        if t.exit_reason == "open":\n            return t\n    return None\n'
_SOURCES['tw_backdraw/futures.py'] = '"""台指期執行版：連續合約、換倉、固定口數的槓桿部位。\n\n與 ETF 版的三個差異\n-------------------\n1. **換倉**：近月合約到期要換到次月。換倉當日以「近月收盤」平倉、\n   「次月同日收盤」建倉，兩者的價差**不計入損益** —— 那是逆價差/正價差，\n   不是賺賠。`build_continuous()` 就是在做這件事。\n\n2. **槓桿由停損距離決定**：ETF 的槓桿是固定的（00631L 為 2 倍），期貨可以自己選。\n   同樣的風險預算下，停損越近就能放越大：\n\n       槓桿 L = 風險預算 ÷ 停損距離，上限 `max_leverage`\n\n   注意這裡**不套用 `min_stop_distance` 下限** —— 那個下限是為了防止\n   固定槓桿的 ETF 算出過大的水位；期貨改由槓桿上限承擔同樣的角色。\n   若保留下限，L 會恆等於 8%/5% = 1.6 倍，槓桿上限永遠碰不到。\n\n3. **進場後不調整口數**：權益變動時實際槓桿會自然漂移（賺錢時下降）。\n   因此持有期間的權益是**線性**於期貨報酬，不是複利：\n\n       權益(t) / 權益(進場) = 1 + L × (F(t)/F(進場) − 1)\n\n4. **當日成交**：加權指數 13:30 收盤、台指期 13:45 收盤，中間有 15 分鐘。\n   訊號以指數收盤判定後，還來得及在**當天的期貨收盤**成交，不必等到隔天。\n   ETF 版沒有這個空間（同一時間收盤），只能次日成交。\n   這個差別對停損特別關鍵 —— 隔夜跳空正是把「假設停損 1.5%」放大成\n   「實際虧損 7.8%」的主因。以 `entries_from_trades(same_day=...)` 切換。\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom datetime import date\n\nfrom .config import StrategyConfig\nfrom .levels import Levels\n\n#: 台指期（TX）每點新台幣，小台（MTX）為 50\nTX_POINT_VALUE = 200.0\n\n\n@dataclass(frozen=True)\nclass FuturesCost:\n    """期貨交易成本（以契約金額比例表示，單邊）。"""\n\n    #: 期交稅：契約金額的十萬分之二\n    tax_rate: float = 0.00002\n    #: 手續費，每口新台幣。換算成比例時需要指數點位與每點價值\n    commission_per_lot: float = 50.0\n    point_value: float = TX_POINT_VALUE\n\n    def one_way_rate(self, index_level: float) -> float:\n        """單邊成本佔契約金額的比例。"""\n        notional = index_level * self.point_value\n        return self.tax_rate + self.commission_per_lot / notional\n\n\ndef build_continuous(dates: list[date], front_close: list[float],\n                     contract: list[str],\n                     next_close_on_roll: dict[date, float]) -> list[float]:\n    """把近月連續序列接成「已還原換倉價差」的可交易序列。\n\n    Args:\n        dates / front_close / contract: 逐日的日期、近月收盤、該日所屬合約月。\n        next_close_on_roll: {換倉日: 次月合約在該日的收盤}。換倉日指的是\n            **舊合約的最後一天**，也就是 `contract` 即將改變的前一天。\n\n    回傳與輸入等長的序列，起點對齊 `front_close[0]`。\n\n    換倉日隔天的報酬改用「次日近月收盤 ÷ 次月在換倉日的收盤」計算，\n    價差因此不落入損益。缺換倉價差資料時退回原始跳動，並在\n    `missing_rolls()` 中可查出是哪幾天。\n    """\n    if not dates:\n        return []\n    out = [front_close[0]]\n    for i in range(1, len(dates)):\n        prev_is_roll = contract[i] != contract[i - 1]\n        base = front_close[i - 1]\n        if prev_is_roll:\n            base = next_close_on_roll.get(dates[i - 1], front_close[i - 1])\n        out.append(out[-1] * (front_close[i] / base) if base else out[-1])\n    return out\n\n\ndef missing_rolls(dates: list[date], contract: list[str],\n                  next_close_on_roll: dict[date, float]) -> list[date]:\n    """列出缺少次月報價、只能沿用原始跳動的換倉日。"""\n    return [dates[i - 1] for i in range(1, len(dates))\n            if contract[i] != contract[i - 1] and dates[i - 1] not in next_close_on_roll]\n\n\ndef futures_leverage(entry_index: float, levels: Levels, cfg: StrategyConfig,\n                     max_leverage: float = 5.0) -> float:\n    """依停損距離決定槓桿倍數，上限 `max_leverage`。\n\n    停損距離的定義與 ETF 版一致（依 `warn_derisk_fraction` 對停損線與失效線加權，\n    停損線含主防線的假跌破緩衝 —— 用警戒線會低估距離、把槓桿放得過大），\n    但**不套用 `min_stop_distance` 下限**，理由見模組說明。\n    """\n    to_warn = max(entry_index - levels.stop_line, 0.0) / entry_index\n    to_trough = max(entry_index - levels.invalidation, 0.0) / entry_index\n    f = cfg.exit.warn_derisk_fraction\n    dist = f * to_warn + (1.0 - f) * to_trough\n    if dist <= 0:\n        return max_leverage\n    return min(max_leverage, cfg.sizing.risk_per_trade / dist)\n\n\n@dataclass(frozen=True)\nclass FuturesTrade:\n    entry_date: date\n    exit_date: date | None\n    entry_index: float\n    entry_futures: float\n    exit_futures: float | None\n    leverage: float\n    stop_distance: float\n    futures_return: float    # 期貨本身的報酬\n    ret: float               # 權益報酬（已扣進出場成本）\n    #: step-down 之後的槓桿（沒有觸發時等於 leverage）\n    final_leverage: float | None = None\n    #: step-down 觸發日（沒有觸發時為 None）\n    step_date: date | None = None\n\n\n@dataclass(frozen=True)\nclass FuturesEntry:\n    """一筆待執行的期貨部位。索引對應 `dates` 的位置。"""\n\n    entry_i: int\n    exit_i: int | None       # None = 持有到資料最後一根\n    leverage: float\n    entry_index: float       # 進場當日的指數收盤\n    stop_distance: float\n    trade: object | None = None   # 產生這筆部位的引擎交易，供逐筆檢視用\n\n\ndef entries_from_trades(trades, bars, cfg: StrategyConfig,\n                        max_leverage: float = 5.0,\n                        same_day: bool = True) -> list["FuturesEntry"]:\n    """把引擎的交易轉成期貨部位。\n\n    引擎的 `Fill.d` 記的是**成交日**，而它的決策發生在前一根 K 的收盤。\n\n    Args:\n        same_day: True 代表當天期貨收盤成交（指數 13:30 收、期貨 13:45 收，\n            中間 15 分鐘足夠下單），成交索引因此往前挪一根；\n            False 則沿用引擎原本的隔日成交。\n    """\n    index_of = {b.d: i for i, b in enumerate(bars)}\n    shift = 1 if same_day else 0\n    out: list[FuturesEntry] = []\n    for t in trades:\n        if not t.fills:\n            continue\n        e_i = max(index_of[t.fills[0].d] - shift, 0)\n        x_i = (max(index_of[t.fills[-1].d] - shift, 0)\n               if len(t.fills) > 1 else None)\n        if x_i is not None and x_i <= e_i:      # 同日進出場，視為未成立\n            continue\n        entry_index = t.setup.trigger_close\n        out.append(FuturesEntry(\n            entry_i=e_i, exit_i=x_i,\n            leverage=futures_leverage(entry_index, t.levels, cfg, max_leverage),\n            entry_index=entry_index,\n            stop_distance=(entry_index - t.levels.stop_line) / entry_index,\n            trade=t))\n    return out\n\n\ndef _step_down(v: float, lev: float, anchor: float, f0: float, fut: float,\n               rate: float, target: float) -> float:\n    """把固定口數部位減到 `target` 倍：平掉多出來的名目，扣一次單邊成本。\n\n    回傳扣完成本後的權益；呼叫端把錨點重設為 (v, 今日期貨, target)。\n    """\n    cur_notional = lev * anchor * fut / f0\n    delta = max(cur_notional - target * v, 0.0)\n    return v - delta * rate\n\n\ndef vehicle_series(dates: list[date], continuous: list[float],\n                   entries: list[FuturesEntry], cost: FuturesCost,\n                   index_close: list[float],\n                   step_gain: float | None = None,\n                   step_leverage: float = 1.0) -> tuple[list[float], list[FuturesTrade]]:\n    """把「固定口數的槓桿期貨部位」攤成一條可餵給回測器的淨值序列。\n\n    空手期間持平；持有期間依 `1 + L × (F/F_entry − 1)` **線性**變動\n    （固定口數，不複利、不再平衡），並在進出場各扣一次單邊成本。\n\n    成本按契約金額計算，所以扣在權益上的比例是 `L × 單邊成本率`。\n\n    Args:\n        step_gain: **step-down**（docs/strategy.md §22）。部位權益相對進場\n            達 `1 + step_gain` 倍時（以期貨連續序列判定、當日期貨收盤成交），\n            把口數減到 `step_leverage` 倍，之後不再加回。`None` 表示關閉。\n            每筆最多觸發一次；出場日不觸發。\n    """\n    nav = [1.0] * len(dates)\n    detail: list[FuturesTrade] = []\n    by_entry = {e.entry_i: e for e in entries}\n\n    equity = 1.0\n    active: FuturesEntry | None = None\n    eq_at_entry = anchor = f0 = lev = 0.0\n    stepped = False\n    step_d: date | None = None\n\n    for i in range(len(dates)):\n        if active is None:\n            e = by_entry.get(i)\n            if e is None:\n                nav[i] = equity\n                continue\n            active = e\n            eq_at_entry = equity\n            lev = e.leverage\n            anchor = equity * (1.0 - lev * cost.one_way_rate(index_close[i]))\n            f0 = continuous[i]\n            stepped, step_d = False, None\n            nav[i] = anchor\n            continue\n\n        v = anchor * (1.0 + lev * (continuous[i] / f0 - 1.0))\n        closing = active.exit_i is not None and i == active.exit_i\n        if closing:\n            v *= (1.0 - lev * cost.one_way_rate(index_close[i]))\n        elif (step_gain is not None and not stepped\n                and v >= eq_at_entry * (1.0 + step_gain) and lev > step_leverage):\n            v = _step_down(v, lev, anchor, f0, continuous[i],\n                           cost.one_way_rate(index_close[i]), step_leverage)\n            anchor, f0, lev = v, continuous[i], step_leverage\n            stepped, step_d = True, dates[i]\n        nav[i] = v\n        if closing:\n            detail.append(FuturesTrade(\n                entry_date=dates[active.entry_i], exit_date=dates[i],\n                entry_index=active.entry_index, entry_futures=continuous[active.entry_i],\n                exit_futures=continuous[i], leverage=active.leverage,\n                stop_distance=active.stop_distance,\n                futures_return=continuous[i] / continuous[active.entry_i] - 1.0,\n                ret=v / eq_at_entry - 1.0,\n                final_leverage=lev, step_date=step_d))\n            equity, active = v, None\n\n    if active is not None:      # 持有到最後一根，未平倉\n        detail.append(FuturesTrade(\n            entry_date=dates[active.entry_i], exit_date=None,\n            entry_index=active.entry_index, entry_futures=continuous[active.entry_i],\n            exit_futures=continuous[-1], leverage=active.leverage,\n            stop_distance=active.stop_distance,\n            futures_return=continuous[-1] / continuous[active.entry_i] - 1.0,\n            ret=nav[-1] / eq_at_entry - 1.0,\n            final_leverage=lev, step_date=step_d))\n    return nav, detail\n\n\n@dataclass(frozen=True)\nclass TradeDetail:\n    """單筆期貨部位的完整檢視：報酬、期間極值，以及當初的進場條件。"""\n\n    trade: FuturesTrade\n    entry: FuturesEntry\n    bars_held: int\n    mfe: float            # 期間最大浮動獲利（權益，相對進場）\n    mae: float            # 期間最大浮動虧損（權益，相對進場）\n    max_drawdown: float   # 期間內從波段高點起算的最大回撤\n\n    # --- 進場條件（來自訊號本身） ---\n    @property\n    def setup(self):\n        return self.entry.trade.setup\n\n    @property\n    def levels(self):\n        return self.entry.trade.levels\n\n    @property\n    def exit_reason(self) -> str:\n        """出場說明。優先用出場那筆成交自己記的理由，比代碼具體。"""\n        t = self.entry.trade\n        if t.exit_reason == "open":\n            return "尚未出場（持有中）"\n        fills = t.fills\n        if len(fills) > 1 and fills[-1].side == "sell":\n            return fills[-1].reason\n        return t.exit_reason\n\n    @property\n    def from_peak(self) -> float:\n        """訊號日距離前高還有多遠（負值＝仍低於前高）。"""\n        s = self.setup\n        return s.trigger_close / s.peak - 1.0\n\n\ndef trade_details(dates: list[date], nav: list[float],\n                  entries: list[FuturesEntry],\n                  detail: list[FuturesTrade]) -> list[TradeDetail]:\n    """把淨值序列切成逐筆部位，算出每筆的 MFE / MAE / 期間最大回撤。\n\n    極值一律以**權益**衡量（已含槓桿與進場成本），所以數字就是帳戶當下看到的\n    浮動盈虧，不是期貨本身的漲跌。\n    """\n    by_entry_date = {dates[e.entry_i]: e for e in entries}\n    out: list[TradeDetail] = []\n    for t in detail:\n        e = by_entry_date.get(t.entry_date)\n        if e is None:\n            continue\n        a = e.entry_i\n        b = e.exit_i if e.exit_i is not None else len(dates) - 1\n        seg = nav[a:b + 1]\n        base = seg[0]\n        if base <= 0:\n            continue\n        peak, dd = base, 0.0\n        for x in seg:\n            peak = max(peak, x)\n            dd = min(dd, x / peak - 1.0)\n        out.append(TradeDetail(\n            trade=t, entry=e, bars_held=b - a,\n            mfe=max(seg) / base - 1.0,\n            mae=min(seg) / base - 1.0,\n            max_drawdown=dd))\n    return out\n\n\ndef format_trade_details(details: list[TradeDetail]) -> str:\n    """逐筆列出交易與當初的進場條件（中文，供 CLI 直接輸出）。"""\n    lines: list[str] = []\n    for n, d in enumerate(details, 1):\n        t, s, lv = d.trade, d.setup, d.levels\n        exit_txt = str(t.exit_date) if t.exit_date else "持有中（尚未平倉）"\n        lines.append(f"[{n}] {t.entry_date} → {exit_txt}\u3000持有 {d.bars_held} 個交易日")\n        lines.append(\n            f"    進場條件：{s.peak_date} 高點 {s.peak:,.0f} → {s.trough_date} 谷底 "\n            f"{s.trough:,.0f}（回檔 {s.drop_pct:.1%}），"\n            f"{s.bars_to_repair} 個交易日補回 {s.repair_fraction:.0%}")\n        lines.append(\n            f"              訊號日指數 {s.trigger_close:,.0f}（距前高 {d.from_peak:+.1%}）"\n            f"\u3000停損線 {lv.stop_line:,.0f}"\n            + (f"（警戒線 {lv.warn_line:,.0f} 再扣假跌破緩衝）"\n               if lv.stop_line < lv.warn_line else "（警戒線）")\n            + f"\u3000失效線 {lv.invalidation:,.0f}")\n        lines.append(\n            f"    距離停損 {t.stop_distance:.2%}\u3000→\u3000槓桿 "\n            f"{t.leverage:.2f}x（風險預算 ÷ 停損距離，上限封頂）")\n        lines.append(\n            f"    期貨報酬 {t.futures_return:+.1%}\u3000權益報酬 {t.ret:+.1%}"\n            f"\u3000最大報酬 {d.mfe:+.1%}\u3000最大不利 {d.mae:+.1%}"\n            f"\u3000期間最大回撤 {d.max_drawdown:.1%}")\n        lines.append(f"    出場原因：{d.exit_reason}")\n        lines.append("")\n    return "\\n".join(lines)\n\n\ndef trend_filter(entries: list["FuturesEntry"], bars, ma_period: int = 200,\n                 below: bool = True) -> list["FuturesEntry"]:\n    """依進場日收盤與均線的位置過濾部位。\n\n    `below=True` 只保留**收盤低於均線**的訊號。這與直覺相反，但這是逆勢策略：\n    要求「站上均線才進場」會結構性排除最深的回檔，而深回檔正是報酬最好的場景\n    （見 docs/strategy.md §18）。均線資料不足的日子一律排除。\n    """\n    from .engine import moving_average\n    ma = moving_average(bars, ma_period)\n    out = []\n    for e in entries:\n        m = ma[e.entry_i]\n        if m is None:\n            continue\n        c = bars[e.entry_i].close\n        if (c < m) if below else (c > m):\n            out.append(e)\n    return out\n\n\ndef fixed_leverage(entries: list["FuturesEntry"], leverage: float) -> list["FuturesEntry"]:\n    """把所有部位改成同一個槓桿倍數，不再依停損距離決定。"""\n    return [FuturesEntry(e.entry_i, e.exit_i, leverage, e.entry_index,\n                         e.stop_distance, e.trade) for e in entries]\n\n\ndef hybrid_entries(entries: list["FuturesEntry"], bars, ma_period: int = 200,\n                   below_leverage: float = 3.0, above_risk_scale: float = 0.5,\n                   above_cap: float | None = None) -> list["FuturesEntry"]:\n    """§20 混合注碼：按進場日與均線的相對位置切換槓桿規則。\n\n        進場日收盤 < MA → 固定 `below_leverage`（深回檔是最好的機會，別壓小注）\n        其餘           → 風險式槓桿 × `above_risk_scale`（反環境訊號只給一半預算），\n                         可再以 `above_cap` 封頂\n\n    均線資料不足的日子歸「其餘」—— 沒有濾網資訊時維持風險式，是保守的選擇。\n    輸入的 `entries` 應來自 `entries_from_trades()`，其 `leverage` 即風險式槓桿。\n    """\n    from .engine import moving_average\n    ma = moving_average(bars, ma_period)\n    out = []\n    for e in entries:\n        m = ma[e.entry_i]\n        if m is not None and bars[e.entry_i].close < m:\n            lev = below_leverage\n        else:\n            lev = e.leverage * above_risk_scale\n            if above_cap is not None:\n                lev = min(lev, above_cap)\n        out.append(FuturesEntry(e.entry_i, e.exit_i, lev, e.entry_index,\n                                e.stop_distance, e.trade))\n    return out\n\n\ndef entry_regime(bars, i: int, ma: list) -> str:\n    """進場日 i 適用哪一種注碼：\'below\'（固定 3x）或 \'above\'（半預算風險式）。"""\n    m = ma[i]\n    return "below" if (m is not None and bars[i].close < m) else "above"\n\n\ndef ma_band_filter(index_close: list[float], ma: list[float | None],\n                   band_up: float = 0.0, band_dn: float = 0.0) -> list[bool]:\n    """核心部位的均線濾網，帶**遲滯緩衝帶**（hysteresis band）。\n\n        關 → 開：收盤 > 均線 × (1 + band_up)\n        開 → 關：收盤 ≤ 均線 × (1 − band_dn)\n\n    兩條門檻中間是無動作區，收盤在均線附近來回不會反覆換邊。這解決的是\n    「站上、跌破、再站上」的空轉，不是交易成本 —— 成本本來就只有十萬分之二\n    的期交稅加每口 50 元手續費（見 `FuturesCost`）。\n\n    `band_up = band_dn = 0` 時**完全等價**於舊版的 `收盤 > 均線`：\n    開啟條件用嚴格大於、關閉條件用小於等於，收盤恰好等於均線時兩者都判為關；\n    均線尚未成形（`ma[i] is None`）則一律判為關，不沿用前一天的狀態\n    —— 指標算不出來就不持有，也讓帶寬 0 逐點重現舊行為。\n\n    狀態只由「收盤與均線的相對位置」決定，與核心當下有沒有真的持有無關。\n    策略部位接手期間濾網照常更新，所以策略平倉後不必重新等一次向上突破。\n    """\n    out: list[bool] = []\n    on = False\n    for c, m in zip(index_close, ma):\n        if m is None:\n            on = False\n        elif not on and c > m * (1.0 + band_up):\n            on = True\n        elif on and c <= m * (1.0 - band_dn):\n            on = False\n        out.append(on)\n    return out\n\n\ndef core_overlay(dates: list[date], continuous: list[float],\n                 entries: list["FuturesEntry"], cost: FuturesCost,\n                 index_close: list[float], core_leverage: float,\n                 ma: list[float | None],\n                 step_gain: float | None = None,\n                 step_leverage: float = 1.0,\n                 band_up: float = 0.0,\n                 band_dn: float = 0.0) -> tuple[list[float], list[FuturesTrade], float]:\n    """在 `vehicle_series` 之上，空手期間補一個低槓桿的核心部位。\n\n    核心只在**策略沒有部位**且**均線濾網為開**時持有，策略一有訊號就先平掉核心。\n    逆勢濾網（`trend_filter(below=True)`）只在收盤**低於**均線時進場，\n    所以兩者天然互斥：低於均線做策略、高於均線抱核心，中間沒有重疊。\n\n    時序與策略一致：`ma`/收盤在第 i 天收盤後判定，部位在當天期貨收盤建立，\n    因此第 i 天的損益由**前一天**的判斷決定 —— 用當天判斷賺當天的報酬是前視偏誤。\n\n    Args:\n        band_up / band_dn: 均線濾網的遲滯緩衝帶，見 `ma_band_filter()`。\n            預設 0 等同舊版的 `收盤 > 均線`，逐日判定。\n\n    回傳 (淨值, 策略交易明細, 有部位的日子佔比)。核心部位不算成交易筆數。\n    """\n    on = ma_band_filter(index_close, ma, band_up, band_dn)\n    by_entry = {e.entry_i: e for e in entries}\n    nav = [1.0] * len(dates)\n    detail: list[FuturesTrade] = []\n    equity, active, eq_at_entry, anchor, f0, lev = 1.0, None, 0.0, 0.0, 0.0, 0.0\n    holding_core, exposed = False, 0\n    stepped, step_d = False, None\n\n    for i in range(len(dates)):\n        if active is not None:\n            v = anchor * (1.0 + lev * (continuous[i] / f0 - 1.0))\n            exposed += 1\n            closing = active.exit_i is not None and i == active.exit_i\n            if closing:\n                v *= 1.0 - lev * cost.one_way_rate(index_close[i])\n            elif (step_gain is not None and not stepped\n                    and v >= eq_at_entry * (1.0 + step_gain) and lev > step_leverage):\n                v = _step_down(v, lev, anchor, f0, continuous[i],\n                               cost.one_way_rate(index_close[i]), step_leverage)\n                anchor, f0, lev = v, continuous[i], step_leverage\n                stepped, step_d = True, dates[i]\n            nav[i] = v\n            if closing:\n                f_entry = continuous[active.entry_i]\n                detail.append(FuturesTrade(\n                    entry_date=dates[active.entry_i], exit_date=dates[i],\n                    entry_index=active.entry_index, entry_futures=f_entry,\n                    exit_futures=continuous[i], leverage=active.leverage,\n                    stop_distance=active.stop_distance,\n                    futures_return=continuous[i] / f_entry - 1.0,\n                    ret=v / eq_at_entry - 1.0,\n                    final_leverage=lev, step_date=step_d))\n                equity, active, holding_core = v, None, False\n            continue\n\n        if i > 0 and holding_core:                 # 昨收就持有核心 → 賺今天\n            equity *= 1.0 + core_leverage * (continuous[i] / continuous[i - 1] - 1.0)\n            exposed += 1\n\n        e = by_entry.get(i)\n        if e is not None:                          # 今收轉進策略部位\n            if holding_core:\n                equity *= 1.0 - core_leverage * cost.one_way_rate(index_close[i])\n                holding_core = False\n            active, eq_at_entry, lev = e, equity, e.leverage\n            anchor = equity * (1.0 - lev * cost.one_way_rate(index_close[i]))\n            f0 = continuous[i]\n            stepped, step_d = False, None\n            nav[i] = anchor\n            exposed += 1\n            continue\n\n        if on[i] != holding_core:                  # 核心進出，各付一次成本\n            equity *= 1.0 - core_leverage * cost.one_way_rate(index_close[i])\n            holding_core = on[i]\n        nav[i] = equity\n\n    if active is not None:\n        f_entry = continuous[active.entry_i]\n        detail.append(FuturesTrade(\n            entry_date=dates[active.entry_i], exit_date=None,\n            entry_index=active.entry_index, entry_futures=f_entry,\n            exit_futures=continuous[-1], leverage=active.leverage,\n            stop_distance=active.stop_distance,\n            futures_return=continuous[-1] / f_entry - 1.0,\n            ret=nav[-1] / eq_at_entry - 1.0,\n            final_leverage=lev, step_date=step_d))\n    return nav, detail, exposed / len(dates)\n'
_SOURCES['tw_backdraw/__init__.py'] = '"""台灣指數「快速修復」回檔入場策略（標的：台灣50正2 / 00631L）。"""\n\nfrom .bars import Bar, load_csv\nfrom .config import DEFAULT_CONFIG, StrategyConfig\nfrom .engine import Engine, Result, Trade, position_size\nfrom .levels import Levels, build_levels\nfrom .plan import TradePlan, build_plan\nfrom .setup import FastRepairSetup, detect_setups\n\n__all__ = [\n    "Bar", "load_csv",\n    "StrategyConfig", "DEFAULT_CONFIG",\n    "Levels", "build_levels",\n    "FastRepairSetup", "detect_setups",\n    "Engine", "Result", "Trade", "position_size",\n    "TradePlan", "build_plan",\n]\n'
_SOURCES['scripts/discord_daily.py'] = '#!/usr/bin/env python3\n"""明日作戰表 → Discord。**前一晚執行。**\n\n    export Finlab_API_token=...\n    export DISCORD_WEBHOOK_URL=https://discord.com/api/webhooks/...\n    python3 scripts/discord_daily.py                 # 送出\n    python3 scripts/discord_daily.py --dry-run       # 只印出，不送\n    python3 scripts/discord_daily.py --only-if-action  # 沒有可能觸發的點位就不吵\n\n注碼規則（docs/strategy.md §20–§22「最終套件」，docs/final_package.md 有完整決策樹）\n------------------------------------------------------------------------------\n    進場日收盤 < MA200 → 固定 3x（每口小台需要 = 收盤 × 50 ÷ 3）\n    進場日收盤 ≥ MA200 → 半預算風險式：4% ÷ 停損距離，上限 2.5x\n                          （每口需要 = (收盤 − 停損線) × 1,250）\n    3x 部位權益達 +150%（期貨自進場價 +50%）→ 減碼到 1x，之後不加回（step-down）\n    空手且收盤 > MA200 → 核心 0.5x\n`--sizing risk --no-step-down` 可切回舊版（8% ÷ 停損距離、上限 5x、不減碼）。\n`--core-band 0.02` 給核心濾網加遲滯緩衝帶，減少均線附近的空轉\n（docs/coverage.md「核心濾網的緩衝帶」）。預設 0＝維持逐日判定。\n\n為什麼改成晚上跑\n----------------\n訊號以**加權指數 13:30 收盤**判定，成交在**當日台指期 13:45 收盤** ——\n中間只有 15 分鐘。收盤後才算、才通知、才下單，時間根本不夠，\n而且雲端排程的延遲完全不可控。\n\n但這些觸發點位**今晚就能全部算出來**：停損線、失效線、進場觸發價、\n均線交叉價、減碼觸發價，全部由已經收盤的資料決定，明天不會變。\n唯一會動的是移動停利線（明天創新高才會往上移），而它只會對你有利。\n\n所以流程改成：**今晚拿到點位表 → 明天 13:30 只需比對收盤價 → 13:45 前下單。**\n明天不必再跑任何程式，也不必等通知。\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport os\nimport sys\nimport urllib.error\nimport urllib.request\nfrom datetime import date\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parent.parent\nsys.path.insert(0, str(ROOT))\nsys.path.insert(0, str(ROOT / "scripts"))\n\nfrom tx_data import load_tx, login                                  # noqa: E402\nfrom tw_backdraw.config import PRESETS, StrategyConfig              # noqa: E402\nfrom tw_backdraw.engine import Engine, moving_average               # noqa: E402\nfrom tw_backdraw.futures import (FuturesCost, entries_from_trades,  # noqa: E402\n                                 entry_regime, futures_leverage,\n                                 hybrid_entries, ma_band_filter,\n                                 trade_details, vehicle_series)\nfrom tw_backdraw.levels import build_levels                         # noqa: E402\nfrom tw_backdraw.setup import detect_setups, scan_episodes          # noqa: E402\n\n#: 依 docs/coverage.md 的驗收結論：空手時持有 0.5x 核心，濾網為指數 > MA200\nCORE_LEVERAGE = 0.5\nCORE_MA = 200\n#: 核心濾網的遲滯緩衝帶（docs/coverage.md §核心濾網的緩衝帶）。\n#: 0 = 逐日 `收盤 > MA200`，與上線以來的行為相同；用 --core-band 才會啟用。\nCORE_BAND = 0.0\n#: §20 混合注碼：均線下固定 3x；均線上風險預算砍半（4%）\nBELOW_LEV = 3.0\nABOVE_RISK_SCALE = 0.5\n#: §22 step-down：權益 +150% → 降到 1x\nSTEP_GAIN = 1.5\nSTEP_LEV = 1.0\nMTX_POINT = 50.0        # 小台每點新台幣\n\nGREEN, BLUE, YELLOW, RED, GREY = 0x2ECC71, 0x3498DB, 0xF1C40F, 0xE74C3C, 0x95A5A6\n\n\ndef pct(x: float) -> str:\n    return f"{x:+.2%}"\n\n\nclass Daily:\n    def __init__(self, cfg: StrategyConfig, max_leverage: float,\n                 as_of: date | None = None, note: str = "",\n                 sizing: str = "hybrid", step_down: bool = True,\n                 core_band: float = CORE_BAND):\n        self.cfg = cfg\n        self.max_leverage = max_leverage\n        self.note = note\n        self.sizing = sizing\n        self.step_down = step_down\n        self.core_band = core_band\n        self.bars, self.fs, self.missing = load_tx()\n        if as_of is not None:            # 回放歷史某一天，用來驗證訊息內容\n            keep = [i for i, b in enumerate(self.bars) if b.d <= as_of]\n            if not keep:\n                raise SystemExit(f"{as_of} 之前沒有資料")\n            self.bars = self.bars[:keep[-1] + 1]\n            self.fs = self.fs[:keep[-1] + 1]\n        self.dates = [b.d for b in self.bars]\n        self.ic = [b.close for b in self.bars]\n        self.ma_series = moving_average(self.bars, CORE_MA)\n        self.ma = self.ma_series[-1]\n        # 核心的開關是**有狀態的**（緩衝帶帶內維持原狀），不能只看今天的收盤\n        self.core_series = ma_band_filter(self.ic, self.ma_series,\n                                          core_band, core_band)\n\n        # 「均線上」規則的風險預算與槓桿上限；均線下固定 BELOW_LEV\n        if sizing == "hybrid":\n            self.risk = cfg.sizing.risk_per_trade * ABOVE_RISK_SCALE\n            self.cap = max_leverage * ABOVE_RISK_SCALE\n        else:\n            self.risk = cfg.sizing.risk_per_trade\n            self.cap = max_leverage\n\n        res = Engine(cfg).run(self.bars, self.fs)\n        ent = entries_from_trades(res.trades, self.bars, cfg, max_leverage,\n                                  same_day=True)\n        if sizing == "hybrid":\n            ent = hybrid_entries(ent, self.bars, CORE_MA, BELOW_LEV, ABOVE_RISK_SCALE)\n        self.ent = ent\n        self.nav, det = vehicle_series(\n            self.dates, self.fs, self.ent, FuturesCost(), self.ic,\n            step_gain=STEP_GAIN if step_down else None, step_leverage=STEP_LEV)\n        self.details = trade_details(self.dates, self.nav, self.ent, det)\n        live: list = []\n        scan_episodes(self.bars, cfg.setup, live)\n        self.live = live[0] if live else None\n        self.setups = detect_setups(self.bars, cfg.setup)\n\n    # ---- 狀態判斷 ----\n    @property\n    def last(self):\n        return self.bars[-1]\n\n    @property\n    def open_trade(self):\n        """目前未平倉的那一筆（沒有就是 None）。"""\n        if not self.details:\n            return None\n        d = self.details[-1]\n        return d if d.trade.exit_date is None else None\n\n    @property\n    def closed_today(self):\n        d = self.details[-1] if self.details else None\n        return d if d and d.trade.exit_date == self.last.d else None\n\n    @property\n    def fired_today(self):\n        """今天收盤剛觸發的訊號。\n\n        不能只看引擎的成交紀錄 —— 引擎的買單掛在訊號日收盤、隔一根 K 才成交，\n        所以「訊號當天」那一根還沒有 fill，`open_trade` 會是 None。\n        但期貨版是**當日期貨收盤**成交，訊號日就是下單日，非抓出來不可。\n        """\n        if not self.setups or self.setups[-1].trigger_date != self.last.d:\n            return None\n        return self.setups[-1]\n\n    def exit_signal_today(self):\n        """今天收盤已經跌破出場線 —— 引擎的賣單要隔一根 K 才成交，\n        所以 `closed_today` 在訊號當天還是空的，必須另外判斷。"""\n        t = self.open_trade\n        if t is None:\n            return None\n        c = self.last.close\n        stop, _ = self.trail_stop(t)\n        if stop is not None and c < stop:\n            return stop, f"移動停利（自波段最高收盤回檔 {self.cfg.exit.trail_drawdown:.0%}）"\n        if c < t.levels.stop_line:\n            return t.levels.stop_line, "跌破停損線"\n        return None\n\n    @property\n    def opened_today(self) -> bool:\n        t = self.open_trade\n        return bool(t and t.trade.entry_date == self.last.d)\n\n    @property\n    def core_on(self) -> bool:\n        """核心濾網今天是開還是關。緩衝帶為 0 時等同 `收盤 > MA200`。"""\n        return self.core_series[-1]\n\n    # ---- 注碼：均線位置、槓桿、每口需要 ----\n    def regime_today(self) -> str:\n        """今天收盤適用哪一種注碼（今天觸發的訊號用）。"""\n        if self.sizing != "hybrid":\n            return "above"\n        return entry_regime(self.bars, len(self.bars) - 1, self.ma_series)\n\n    def regime_tomorrow(self, close: float) -> str:\n        """明天若收在 `close`，適用哪一種注碼。均線交叉價今晚就能算。"""\n        if self.sizing != "hybrid":\n            return "above"\n        cross = self.ma_cross_tomorrow()\n        return "below" if (cross is not None and close < cross) else "above"\n\n    def entry_leverage(self, close: float, lv, regime: str) -> float:\n        if regime == "below":\n            return BELOW_LEV\n        base = futures_leverage(close, lv, self.cfg, self.max_leverage)\n        return base * ABOVE_RISK_SCALE if self.sizing == "hybrid" else base\n\n    #: 均線上：每口小台所需權益 = 每點價值 ÷ 風險預算 × (收盤 − 停損線)\n    @property\n    def per_point(self) -> float:\n        return MTX_POINT / self.risk      # 50 ÷ 4% = 1,250（舊版 50 ÷ 8% = 625）\n\n    def cap_below(self, stop_line: float) -> float:\n        """低於這個收盤價，槓桿會撞到上限，改用「收盤 × 每點價值 ÷ 上限」。"""\n        m = self.cap\n        return stop_line * m / (m - self.risk)\n\n    def lot_cost(self, close: float, stop_line: float, regime: str) -> float:\n        """在這個收盤價與注碼下，一口小台需要多少權益。"""\n        if regime == "below":\n            return close * MTX_POINT / BELOW_LEV\n        if close < self.cap_below(stop_line):\n            return close * MTX_POINT / self.cap\n        return self.per_point * (close - stop_line)\n\n    def lot_formula(self, regime: str, stop_line: float | None = None) -> str:\n        if regime == "below":\n            return f"收盤 × {MTX_POINT:g} ÷ {BELOW_LEV:g}"\n        s = f"{stop_line:,.0f}" if stop_line is not None else "停損線"\n        return f"(收盤 − {s}) × {self.per_point:.0f}"\n\n    # ---- step-down ----\n    def step_trigger(self, t):\n        """3x 部位的減碼觸發：期貨自進場 +50%（權益 +150%）。回傳 (期貨倍率, 指數參考價) 或 None。"""\n        if not self.step_down or t is None:\n            return None\n        tr = t.trade\n        if tr.leverage <= STEP_LEV or tr.step_date is not None:\n            return None\n        ratio = 1.0 + STEP_GAIN / tr.leverage        # 3x：1.5 倍\n        return ratio, tr.entry_index * ratio\n\n    def stepped_today(self) -> bool:\n        t = self.open_trade\n        return bool(t and t.trade.step_date == self.last.d)\n\n    def current_leverage(self, t) -> float:\n        tr = t.trade\n        return tr.final_leverage if tr.final_leverage is not None else tr.leverage\n\n    # ---- 三個區塊 ----\n    def tomorrow_plan(self) -> tuple[str, str, int]:\n        """明天 13:30 要比對的點位與對應動作。回傳 (標題, 內容, 顏色)。\n\n        這裡列出的每一個價位都由**已收盤**的資料決定，明天不會變動 ——\n        所以今晚就能定案，明天只要比對收盤價。\n        """\n        c = self.last.close\n        t = self.open_trade\n        cfg = self.cfg\n\n        hit = self.exit_signal_today()\n        if hit is not None:\n            line, why = hit\n            return ("🔴 今天已觸發出場",\n                    f"**收盤 {c:,.0f} 已跌破 {line:,.0f}（{why}）**\\n"\n                    f"→ 今日 13:45 前全數平倉；若已錯過，明天開盤補平。", RED)\n\n        if t is not None:\n            lv = t.levels\n            stop, why = self.trail_stop(t)\n            # 兩條出場線同時存在時，較**高**的那條會先被碰到\n            binding = max(lv.stop_line, stop) if stop is not None else lv.stop_line\n            mark = lambda x: "\u3000←\u3000**先碰到這條**" if x == binding else ""\n            rows = [\n                f"🔴 收盤 **< {lv.stop_line:,.0f}**（{pct(lv.stop_line / c - 1)}）"\n                f"\u3000→\u300013:45 前**全數平倉**{mark(lv.stop_line)}",\n            ]\n            if stop is not None:\n                rows.append(\n                    f"🔴 收盤 **< {stop:,.0f}**（{pct(stop / c - 1)}）"\n                    f"\u3000→\u3000移動停利，**全數平倉**{mark(stop)}")\n                rows.append(\n                    f"\u3000\u3000_{why}明天若收更高，這條線跟著上移到「新高 ×"\n                    f" {1 - cfg.exit.trail_drawdown:.2f}」，只會對你有利。_")\n            else:\n                need = t.setup.peak\n                rows.append(\n                    f"⬆️ 收盤 **> {need:,.0f}**（{pct(need / c - 1)}）"\n                    f"\u3000→\u3000創前高，**啟動移動停利**"\n                    f"（自此以波段最高收盤回檔 {cfg.exit.trail_drawdown:.0%} 出場）")\n            st = self.step_trigger(t)\n            if st is not None:\n                ratio, idx_ref = st\n                rows.append(\n                    f"🔻 期貨收盤 **≥ 你的進場價 × {ratio:.2f}**（指數參考 ≈ {idx_ref:,.0f}，"\n                    f"{pct(idx_ref / c - 1)}）\u3000→\u3000**減碼到 {STEP_LEV:g}x**："\n                    f"口數 = 權益 ÷ (收盤 × {MTX_POINT:g})，之後不加回")\n            elif t.trade.step_date is not None:\n                rows.append(f"\u3000\u3000_已於 {t.trade.step_date} 減碼至 {STEP_LEV:g}x，不再調整口數。_")\n            rows.append(f"🟡 以上都沒發生\u3000→\u3000**續抱，不動作**")\n            colour = YELLOW if c / lv.stop_line - 1 < 0.02 else GREEN\n            return ("📋 明日作戰表（持有中）", "\\n".join(rows), colour)\n\n        w = self.live\n        if w is not None and w.state == "drawdown":\n            trig = w.trigger_close(cfg.setup)\n            if w.bars_left <= 0:\n                return ("📋 明日作戰表（空手）",\n                        f"⚪ 修復視窗已用盡（{cfg.setup.max_repair_bars} 日），"\n                        f"這一段回檔作廢。\\n"\n                        f"明天起重新以區間最高點為錨，**不會有進場訊號**。", GREY)\n            lv = build_levels(w.peak, w.trough, cfg.levels)\n            reg = self.regime_tomorrow(trig)\n            lev = self.entry_leverage(trig, lv, reg)\n            rows = [\n                f"🟢 收盤 **≥ {trig:,.0f}**（{pct(trig / c - 1)}）"\n                f"\u3000→\u300013:45 前**買進**，"\n                f"每 **{self.lot_cost(trig, lv.stop_line, reg):,.0f}** 元 1 口小台"\n                f"（{\'固定 3x\' if reg == \'below\' else f\'槓桿約 {lev:.2f}x\'}）",\n                f"\u3000\u3000_進場後停損線 {lv.stop_line:,.0f}、失效線 {lv.invalidation:,.0f}，"\n                f"兩條都已固定，不隨進場價變動。_",\n            ]\n            rows.append(self.regime_note(trig, lv.stop_line, reg))\n            rows += [\n                f"🔻 收盤 **< {w.trough:,.0f}**（{pct(w.trough / c - 1)}）"\n                f"\u3000→\u3000破底，谷底與計時**全部重來**，觸發價跟著下移",\n                f"⚪ 介於兩者之間\u3000→\u3000**不動作**，視窗剩 **{w.bars_left - 1}** 個交易日",\n            ]\n            colour = GREEN if trig / c - 1 < 0.01 else BLUE\n            return ("📋 明日作戰表（空手・追蹤中）", "\\n".join(rows), colour)\n\n        if w is not None and w.state == "expired":\n            return ("📋 明日作戰表（空手）",\n                    f"⚪ 上一段回檔已過期。等收盤重新站上 **{w.peak:,.0f}**"\n                    f"（{pct(w.peak / c - 1)}）才會重新開始追蹤。\\n明天無動作。", GREY)\n\n        anchor = w.peak if w else c\n        start = anchor * (1 - cfg.setup.min_drawdown)\n        return ("📋 明日作戰表（空手）",\n                f"⚪ 目前沒有在追蹤的回檔，明天**不會有進場訊號**。\\n"\n                f"🔻 收盤 **< {start:,.0f}**（{pct(start / c - 1)}）"\n                f"\u3000→\u3000自高點 {anchor:,.0f} 回檔滿 {cfg.setup.min_drawdown:.0%}，"\n                f"開始追蹤新的一段（那天仍不進場）", GREY)\n\n    def regime_note(self, trig: float, stop_line: float, reg: str) -> str:\n        """說明明天的注碼取決於收盤與 MA200 交叉價的相對位置。"""\n        if self.sizing != "hybrid":\n            return "\u3000\u3000_收得越高、離停損越遠，每口要的錢就越多 —— 見下方速查表。_"\n        cross = self.ma_cross_tomorrow()\n        if cross is None:\n            return f"\u3000\u3000_均線資料不足，一律用半預算：每口 = {self.lot_formula(\'above\', stop_line)}。_"\n        if reg == "below":\n            return (f"\u3000\u3000_觸發價在 MA200 交叉價 {cross:,.0f} 之下 → **固定 3x**"\n                    f"（每口 = {self.lot_formula(\'below\')}）；若收盤反而 ≥ {cross:,.0f}，"\n                    f"改半預算：每口 = {self.lot_formula(\'above\', stop_line)}。_")\n        return (f"\u3000\u3000_觸發價已在 MA200 交叉價 {cross:,.0f} 之上 → **半預算**"\n                f"（每口 = {self.lot_formula(\'above\', stop_line)}，上限 {self.cap:g}x）。_")\n\n    def trail_stop(self, t):\n        """已創高時的移動停利價位。"""\n        s = t.setup\n        i0 = self.dates.index(t.trade.entry_date)\n        hi = max(self.ic[i0:])\n        if hi < s.peak:\n            return None, ""\n        d = self.cfg.exit.trail_drawdown\n        return hi * (1 - d), f"波段最高收盤 {hi:,.0f}，移動停利 {d:.0%}。"\n\n    def sizing_block(self) -> str:\n        """收盤後只要做一次減法、一次乘法就能算出口數。"""\n        t = self.open_trade\n        if t is not None:\n            tr, lv = t.trade, t.levels\n            reg = "below" if tr.leverage == BELOW_LEV and self.sizing == "hybrid" else "above"\n            cur = self.current_leverage(t)\n            lines = ["```",\n                     f"停損線 {lv.stop_line:,.0f}\u3000（進場時已定，不變）",\n                     "",\n                     f"進場口數依據：每口 =（{self.lot_formula(reg, lv.stop_line)}）"\n                     f"→ ({tr.entry_index:,.0f}) 時 {self.lot_cost(tr.entry_index, lv.stop_line, reg):,.0f} 元/口"\n                     f"（＝槓桿 {tr.leverage:.2f}x）"]\n            if tr.step_date is not None:\n                lines.append(f"已於 {tr.step_date} 減碼至 {cur:g}x：每口 = 收盤 × {MTX_POINT:g}")\n            elif self.step_trigger(t) is not None:\n                ratio, idx_ref = self.step_trigger(t)\n                lines.append(f"減碼觸發：期貨 ≥ 進場價 × {ratio:.2f}（指數參考 {idx_ref:,.0f}）"\n                             f"→ 口數 = 權益 ÷ (收盤 × {MTX_POINT:g})")\n            lines.append("```")\n            return "\\n".join(lines)\n\n        w = self.live\n        if w is None or w.state != "drawdown" or w.bars_left <= 0:\n            return ("目前沒有可進場的劇本，暫時用不到。\\n"\n                    f"_通則：均線下 每口 = {self.lot_formula(\'below\')}；"\n                    f"均線上 每口 = {self.lot_formula(\'above\')}_")\n        lv = build_levels(w.peak, w.trough, self.cfg.levels)\n        stop = lv.stop_line\n        trig = w.trigger_close(self.cfg.setup)\n        cross = self.ma_cross_tomorrow()\n        lines = ["```", f"停損線 {stop:,.0f}\u3000（今晚已定，明天不變）"]\n        if self.sizing == "hybrid" and cross is not None:\n            lines += [f"MA200 交叉價 {cross:,.0f}",\n                      "",\n                      f"收盤 < {cross:,.0f}：每口小台需要 = {self.lot_formula(\'below\')}",\n                      f"收盤 ≥ {cross:,.0f}：每口小台需要 = {self.lot_formula(\'above\', stop)}"]\n        else:\n            lines += ["", f"每口小台需要 = {self.lot_formula(\'above\', stop)}"]\n        lines += ["口\u3000\u3000\u3000數   = 你的權益 ÷ 上面那個數，無條件捨去", "```"]\n\n        rows = ["```", f"{\'明天收盤\':>9}{\'注碼\':>5}{\'每口需要\':>11}{\'100萬\':>7}{\'300萬\':>7}{\'500萬\':>7}"]\n        for c in (trig, trig * 1.005, trig * 1.01, trig * 1.02, trig * 1.03):\n            reg = self.regime_tomorrow(c)\n            cost = self.lot_cost(c, stop, reg)\n            rows.append(f"{c:>9,.0f}{\'3x\' if reg == \'below\' else \'半\':>5}{cost:>11,.0f}"\n                        + "".join(f"{int(cap_ // cost):>7}" for cap_ in (1e6, 3e6, 5e6)))\n        rows.append("```")\n        lines += ["速查表（觸發價起算）"] + rows\n        if self.sizing == "hybrid":\n            lines.append(f"_均線下固定 {BELOW_LEV:g}x；均線上 {self.per_point:.0f} = 小台每點 "\n                         f"{MTX_POINT:g} 元 ÷ 風險預算 {self.risk:.0%}（上限 {self.cap:g}x）。_")\n        else:\n            lines.append(f"_{self.per_point:.0f} = 小台每點 {MTX_POINT:g} 元 ÷ 風險預算 "\n                         f"{self.risk:.0%}；等價於「每筆最多虧掉權益的 {self.risk:.0%}」。_")\n        return "\\n".join(lines)\n\n    def today(self) -> str:\n        """今天收盤該做的事（若你今天沒跑腳本，這裡補告訴你）。"""\n        fired = self.fired_today\n        if fired is not None:\n            lv = build_levels(fired.peak, fired.trough, self.cfg.levels)\n            reg = self.regime_today()\n            lev = self.entry_leverage(self.last.close, lv, reg)\n            return (f"🟢 **今天收盤觸發進場訊號** —— 若尚未建立部位，"\n                    f"明天開盤補進（{\'固定 3x\' if reg == \'below\' else f\'槓桿 {lev:.2f}x\'}），"\n                    f"但進場價會與訊號日不同，風險略高於回測假設。\\n"\n                    f"{fired.peak_date} 高點 {fired.peak:,.0f} → {fired.trough_date} "\n                    f"谷底 {fired.trough:,.0f}（回檔 {fired.drop_pct:.1%}），"\n                    f"{fired.bars_to_repair} 日補回 {fired.repair_fraction:.0%}")\n        if self.closed_today:\n            t = self.closed_today\n            return (f"🔴 **今天收盤出場** —— {t.exit_reason}\\n"\n                    f"本筆權益報酬 **{t.trade.ret:+.1%}**"\n                    f"（持有 {t.bars_held} 個交易日）")\n        if self.stepped_today():\n            t = self.open_trade\n            return (f"🔻 **今天收盤觸發減碼** —— 權益已達 +{STEP_GAIN:.0%}，"\n                    f"應已減碼至 {STEP_LEV:g}x（口數 = 權益 ÷ (收盤 × {MTX_POINT:g})）。"\n                    f"沒做的話明天開盤補做。")\n        t = self.open_trade\n        if t is not None:\n            lv = t.levels\n            c = self.last.close\n            zone = {"breakout": "已站上前高", "healthy": "劇本正常",\n                    "buffer": "主防線假跌破容忍區", "caution": "已跌破主防線",\n                    "warning": "已跌破警戒線", "invalidated": "已跌破谷底"}[lv.zone(c)]\n            return f"沒有動作，續抱。分區：{zone}。"\n        return "沒有動作，空手。"\n\n    def position(self) -> str:\n        t = self.open_trade\n        if t is None:\n            return "目前空手。"\n        s, lv, tr = t.setup, t.levels, t.trade\n        c = self.last.close\n        stop, why = self.trail_stop(t)\n        cur = self.current_leverage(t)\n        lev_txt = (f"槓桿 **{tr.leverage:.2f}x**" if tr.step_date is None\n                   else f"槓桿 {tr.leverage:.2f}x → **已減碼 {cur:g}x**（{tr.step_date}）")\n        lines = [\n            f"進場 **{tr.entry_date}** @ 指數 {tr.entry_index:,.0f}"\n            f"\u3000{lev_txt}\u3000持有 {t.bars_held} 日",\n            f"訊號 {s.peak_date} 高點 {s.peak:,.0f} → {s.trough_date} 谷底 {s.trough:,.0f}"\n            f"（回檔 {s.drop_pct:.1%}），{s.bars_to_repair} 日補回 {s.repair_fraction:.0%}",\n            f"目前指數 {c:,.0f}\u3000期貨報酬 {tr.futures_return:+.1%}"\n            f"\u3000**權益報酬 {tr.ret:+.1%}**",\n            f"最大報酬 {t.mfe:+.1%}\u3000最大不利 {t.mae:+.1%}\u3000期間最大回撤 {t.max_drawdown:.1%}",\n            f"停損線 **{lv.stop_line:,.0f}**（{pct(lv.stop_line / c - 1)}）"\n            f"\u3000失效線 {lv.invalidation:,.0f}（{pct(lv.invalidation / c - 1)}）",\n        ]\n        if stop is not None:\n            lines.append(f"移動停利 **{stop:,.0f}**（{pct(stop / c - 1)}）\u3000{why}")\n        return "\\n".join(lines)\n\n    def script(self) -> str:\n        w = self.live\n        c = self.last.close\n        if w is None:\n            return "沒有資料。"\n        if w.state == "engaged":\n            return (f"訊號已觸發並在部位中。前高錨點 {w.peak:,.0f}"\n                    f"（{w.peak_date}）")\n        if w.state == "drawdown":\n            trig = w.trigger_close(self.cfg.setup)\n            lines = [\n                f"追蹤中：{w.peak_date} 高點 {w.peak:,.0f} → {w.trough_date} 谷底 "\n                f"{w.trough:,.0f}（回檔 **{w.drop_pct:.1%}**）",\n                f"谷底後 {w.bars_since_trough} 日，目前補回 **{w.repair_fraction:.0%}**"\n                f"（視窗內最佳 {w.best_in_window:.0%}）",\n                f"觸發條件：{self.cfg.setup.max_repair_bars} 日內收盤補回 "\n                f"{self.cfg.setup.repair_fraction:.0%}\u3000→\u3000收盤需 ≥ **{trig:,.0f}**"\n                f"（{pct(trig / c - 1)}）",\n                f"視窗剩 **{w.bars_left}** 個交易日"\n                + ("\u3000⚠️ 期限將至" if w.bars_left <= 5 else ""),\n            ]\n            if w.lower_lows:\n                lines.append(f"期間破底 {w.lower_lows} 次（每次都讓計時歸零）")\n            return "\\n".join(lines)\n        if w.state == "expired":\n            return f"上一段回檔已過期，等指數重新站上 {w.peak:,.0f} 才重新追蹤。"\n        return (f"沒有在追蹤的回檔。目前高點錨點 {w.peak:,.0f}（{w.peak_date}），"\n                f"跌破 **{w.peak * (1 - self.cfg.setup.min_drawdown):,.0f}**"\n                f"（{pct((1 - self.cfg.setup.min_drawdown) * w.peak / c - 1)}）"\n                f"才開始追蹤新的一段。")\n\n    def core(self) -> str:\n        c = self.last.close\n        if self.ma is None:\n            return "資料不足，無法計算均線。"\n        above = c / self.ma - 1\n        on, band = self.core_on, self.core_band\n        line = (f"MA{CORE_MA} = {self.ma:,.0f}，"\n                f"指數{\'站上\' if above > 0 else \'跌破\'}均線 {above:+.1%}")\n        if band:\n            line += (f"\\n緩衝帶 ±{band:.0%}："\n                     f"開啟 {self.ma * (1 + band):,.0f}／"\n                     f"關閉 {self.ma * (1 - band):,.0f}\u3000→\u3000帶內維持原狀，不動作")\n        # 開著就盯關閉門檻，關著就盯開啟門檻 —— 另一條這時碰不到\n        cross = self.ma_cross_tomorrow((1 - band) if on else (1 + band))\n        if cross is not None:\n            if not band:\n                label, side = "交叉價", "跌破" if on else "站上"\n            else:\n                label, side = ("關閉門檻", "關閉核心") if on else ("開啟門檻", "開啟核心")\n            line += (f"\\n明日{label} **{cross:,.0f}**（{pct(cross / c - 1)}）"\n                     f"\u3000→\u3000收在這之{\'下\' if on else \'上\'}就{side}")\n        if self.open_trade is not None:\n            return line + ("\\n→ 目前有策略部位，**核心部位不啟用**"\n                           "（核心只在策略空手時填補曝險）")\n        state = "**持有中**" if self.core_on else "**空手**"\n        return line + f"\\n→ 策略空手，核心 {CORE_LEVERAGE:g}x {state}"\n\n    def ma_cross_tomorrow(self, k: float = 1.0) -> float | None:\n        """明天恰好讓「收盤 = 均線 × k」成立的收盤價。\n\n        明日均線 = (前 N-1 根收盤和 S + 明日收盤 c) / N，令 c = k × 均線：\n\n            c = k(S + c)/N\u3000→\u3000c(N − k) = kS\u3000→\u3000c = kS / (N − k)\n\n        今晚就能算出確切的門檻，不必等明天。`k = 1` 是均線交叉價本身\n        （注碼用）；`k = 1 ± 緩衝帶` 是核心濾網的開啟／關閉門檻。\n        """\n        if len(self.ic) < CORE_MA:\n            return None\n        return k * sum(self.ic[-(CORE_MA - 1):]) / (CORE_MA - k)\n\n    def has_action(self) -> bool:\n        """明天是否有實際可能被觸發的點位（用於 --only-if-action）。"""\n        if (self.fired_today or self.opened_today or self.closed_today\n                or self.exit_signal_today() or self.stepped_today()):\n            return True\n        t = self.open_trade\n        if t is not None:\n            c = self.last.close\n            stop, _ = self.trail_stop(t)\n            if stop is not None and c / stop - 1 < 0.03:\n                return True\n            st = self.step_trigger(t)\n            if st is not None:\n                i0 = self.dates.index(t.trade.entry_date)\n                if self.fs[-1] / self.fs[i0] >= st[0] * 0.97:\n                    return True\n            return c / t.levels.stop_line - 1 < 0.03\n        w = self.live\n        if w and w.state == "drawdown":\n            trig = w.trigger_close(self.cfg.setup)\n            return trig / self.last.close - 1 < 0.03 or w.bars_left <= 3\n        return False\n\n    # ---- Discord payload ----\n    # ---- 精簡版：13:30 只需要看這幾行 ----\n    def compact(self) -> tuple[str, str, int]:\n        c = self.last.close\n        t = self.open_trade\n        cfg = self.cfg\n        head = [f"`{self.last.d}` 收 **{c:,.0f}**"]\n        rows: list[str] = []\n\n        fired = self.fired_today\n        if fired is not None:\n            lv = build_levels(fired.peak, fired.trough, cfg.levels)\n            reg = self.regime_today()\n            cost = self.lot_cost(c, lv.stop_line, reg)\n            # 這則訊息在收盤後才送達，13:45 的下單窗口已經過了 ——\n            # 所以是「確認」而非「指示」，寫成命令句會讓人以為還來得及。\n            return ("🟢 今天已觸發進場",\n                    "\\n".join(head + ["",\n                        f"✅ 依昨日作戰表，**應已在 13:45 前買進** —— "\n                        f"每口 {cost:,.0f}（口數 = 權益 ÷ {cost:,.0f}，捨去；"\n                        f"{\'固定 3x，均線下\' if reg == \'below\' else \'半預算，均線上\'}）",\n                        f"停損 **{lv.stop_line:,.0f}**（{lv.stop_line / c - 1:+.1%}）"\n                        f"\u3000失效 {lv.invalidation:,.0f}",\n                        f"回檔 {fired.drop_pct:.1%}，"\n                        f"{fired.bars_to_repair} 日補回 {fired.repair_fraction:.0%}", "",\n                        "❗ 沒買到 → **放棄這一筆**，不要隔天追。"\n                        "進場價與停損距離都會偏離回測假設，風險更高。"]),\n                    GREEN)\n        d0 = self.closed_today\n        hit = self.exit_signal_today()\n        if d0 or hit:\n            if d0:\n                why, ret, held = d0.exit_reason, d0.trade.ret, d0.bars_held\n            else:\n                line, why = hit\n                why = f"{why} {line:,.0f}"\n                ret, held = t.trade.ret, t.bars_held\n            return ("🔴 今天已觸發出場",\n                    "\\n".join(head + ["",\n                        f"✅ 依昨日作戰表，**應已在 13:45 前平倉** —— {why}",\n                        f"本筆 **{ret:+.1%}**（持有 {held} 日）", "",\n                        "❗ 沒賣掉 → **明天開盤立刻平倉**，不要等反彈。"]), RED)\n\n        if t is not None:\n            lv = t.levels\n            tr = t.trade\n            stop, _ = self.trail_stop(t)\n            binding = max(lv.stop_line, stop) if stop is not None else lv.stop_line\n            if self.stepped_today():\n                head.append(f"🔻 **今天已觸發減碼**：權益 +{STEP_GAIN:.0%}，應已減碼至 {STEP_LEV:g}x"\n                            f"（口數 = 權益 ÷ (收盤 × {MTX_POINT:g})）")\n            rows.append(f"🔴 跌破 **{binding:,.0f}**（{binding / c - 1:+.1%}）→ 13:45 前平倉")\n            if stop is None:\n                rows.append(f"⬆️ 站上 **{t.setup.peak:,.0f}**"\n                            f"（{t.setup.peak / c - 1:+.1%}）→ 啟動移動停利")\n            st = self.step_trigger(t)\n            if st is not None:\n                ratio, idx_ref = st\n                rows.append(f"🔻 期貨 ≥ 進場價×{ratio:.2f}（指數≈{idx_ref:,.0f}，"\n                            f"{idx_ref / c - 1:+.1%}）→ 減碼到 {STEP_LEV:g}x")\n            rows.append("🟡 其餘 → 不動作")\n            cur = self.current_leverage(t)\n            lev_txt = f"{tr.leverage:.2f}x" if tr.step_date is None else f"{tr.leverage:.2f}x→{cur:g}x"\n            reg = "below" if tr.leverage == BELOW_LEV and self.sizing == "hybrid" else "above"\n            tail = (f"持有 `{tr.entry_date:%m-%d}` 進場 · {lev_txt} · "\n                    f"**{tr.ret:+.1%}** · 進場每口 {self.lot_cost(tr.entry_index, lv.stop_line, reg):,.0f}")\n            colour = YELLOW if c / binding - 1 < 0.02 else GREEN\n            title = "🟡 續抱" if colour == GREEN else "🟠 貼近出場線"\n            return (title, "\\n".join(head + [""] + rows + ["", tail]), colour)\n\n        w = self.live\n        if w is not None and w.state == "drawdown" and w.bars_left > 0:\n            lv = build_levels(w.peak, w.trough, cfg.levels)\n            trig = w.trigger_close(cfg.setup)\n            reg = self.regime_tomorrow(trig)\n            head[0] += f" · 視窗剩 **{w.bars_left - 1}** 日"\n            rows = [\n                f"🟢 站上 **{trig:,.0f}**（{trig / c - 1:+.1%}）→ 買進，"\n                f"每口 {self.lot_cost(trig, lv.stop_line, reg):,.0f}"\n                f"（{\'固定 3x\' if reg == \'below\' else \'半預算\'}）",\n                f"🔻 跌破 **{w.trough:,.0f}**（{w.trough / c - 1:+.1%}）→ 破底重來",\n                "⚪ 其餘 → 不動作",\n            ]\n            cross = self.ma_cross_tomorrow()\n            if self.sizing == "hybrid" and cross is not None:\n                tail = (f"口數 = 權益 ÷ [收盤 < {cross:,.0f}：{self.lot_formula(\'below\')}；"\n                        f"否則 {self.lot_formula(\'above\', lv.stop_line)}]，捨去"\n                        f"\u3000進場後停損 {lv.stop_line:,.0f}")\n            else:\n                tail = (f"口數 = 權益 ÷ [{self.lot_formula(\'above\', lv.stop_line)}]，捨去"\n                        f"\u3000進場後停損 {lv.stop_line:,.0f}")\n            colour = GREEN if trig / c - 1 < 0.01 else BLUE\n            return ("⚪ 追蹤中", "\\n".join(head + [""] + rows + ["", tail]), colour)\n\n        if w is not None and w.state == "expired":\n            return ("⚪ 空手", "\\n".join(head + ["", f"上一段已過期，"\n                    f"收盤重新站上 **{w.peak:,.0f}**（{w.peak / c - 1:+.1%}）才重新追蹤"]), GREY)\n\n        anchor = w.peak if w else c\n        start = anchor * (1 - cfg.setup.min_drawdown)\n        return ("⚪ 空手", "\\n".join(head + ["", "明天不會有訊號",\n                f"🔻 跌破 **{start:,.0f}**（{start / c - 1:+.1%}）→ 開始追蹤新的一段"]), GREY)\n\n    def rule_tag(self) -> str:\n        step = f"\u3000減碼 +{STEP_GAIN:.0%}→{STEP_LEV:g}x" if self.step_down else ""\n        band = f"\u3000核心緩衝帶 ±{self.core_band:.0%}" if self.core_band else ""\n        if self.sizing == "hybrid":\n            return (f"注碼 均線下 {BELOW_LEV:g}x／均線上 "\n                    f"{self.risk:.0%}÷停損距離≤{self.cap:g}x" + step + band)\n        return (f"參數組 tuned\u3000槓桿上限 {self.max_leverage:g}x" + step + band)\n\n    def payload(self, full: bool = False) -> dict:\n        note = f"{self.note}\\n" if self.note else ""\n        if not full:\n            title, body, colour = self.compact()\n            return {"embeds": [{"title": title, "description": note + body,\n                                "color": colour,\n                                "footer": {"text": "13:30 比對收盤價，13:45 前下單"\n                                                   "\u3000|\u3000--full 看完整版"}}]}\n\n        title, body, colour = self.tomorrow_plan()\n        fields = [\n            {"name": "① 明天 13:30 比對收盤價", "value": body, "inline": False},\n            {"name": "② 收盤後怎麼算口數", "value": self.sizing_block(), "inline": False},\n            {"name": "③ 今天發生了什麼", "value": self.today(), "inline": False},\n            {"name": "④ 部位現況", "value": self.position(), "inline": False},\n            {"name": "⑤ 劇本追蹤", "value": self.script(), "inline": False},\n            {"name": f"⑥ 核心部位（MA{CORE_MA} 濾網）", "value": self.core(),\n             "inline": False},\n        ]\n        foot = (f"點位由已收盤資料決定，明天不會變\u3000|\u3000"\n                f"下單窗口 13:30–13:45\u3000|\u3000{self.rule_tag()}")\n        if self.missing:\n            foot += f"\u3000|\u3000⚠️ {len(self.missing)} 個換倉日缺次月報價"\n        return {"embeds": [{\n            "title": title,\n            "description": note + f"依據 **{self.last.d}** 收盤 "\n                                  f"**{self.last.close:,.2f}**\u3000→\u3000下一個交易日的作法",\n            "color": colour,\n            "fields": fields,\n            "footer": {"text": foot},\n        }]}\n\n\ndef post(url: str, payload: dict) -> None:\n    req = urllib.request.Request(\n        url, data=json.dumps(payload).encode("utf-8"),\n        headers={"Content-Type": "application/json",\n                 "User-Agent": "tw-backdraw-daily/1.0"})\n    with urllib.request.urlopen(req, timeout=30) as r:\n        if r.status not in (200, 204):\n            raise RuntimeError(f"Discord 回應 {r.status}")\n\n\ndef render_text(p: dict) -> str:\n    e = p["embeds"][0]\n    out = [e["title"], e["description"], ""]\n    for f in e.get("fields", []):\n        out += [f"── {f[\'name\']} ──", f["value"], ""]\n    out.append(e["footer"]["text"])\n    return "\\n".join(out).replace("**", "").replace("`", "")\n\n\ndef main(argv: list[str] | None = None) -> int:\n    ap = argparse.ArgumentParser(description="每日訊號推送到 Discord")\n    ap.add_argument("--webhook", default=os.environ.get("DISCORD_WEBHOOK_URL"))\n    ap.add_argument("--preset", default="tuned")\n    ap.add_argument("--max-leverage", type=float, default=5.0)\n    ap.add_argument("--sizing", default="hybrid", choices=("hybrid", "risk"),\n                    help="hybrid＝§20 混合注碼（預設）；risk＝舊版 8%% ÷ 停損距離")\n    ap.add_argument("--no-step-down", action="store_true",\n                    help="關閉 §22 的 step-down（權益 +150%% → 降到 1x）")\n    ap.add_argument("--core-band", type=float, default=CORE_BAND, metavar="X",\n                    help="核心濾網的遲滯緩衝帶，例如 0.02 代表站上 MA200×1.02 才開、"\n                         "跌破 MA200×0.98 才關。預設 %(default)g＝逐日判定")\n    ap.add_argument("--dry-run", action="store_true", help="只印出，不送出")\n    ap.add_argument("--only-if-action", action="store_true",\n                    help="沒有動作也沒有接近觸發時，不送訊息")\n    ap.add_argument("--stale-days", type=int, default=5,\n                    help="資料落後超過這麼多天就警告")\n    ap.add_argument("--as-of", default=None, metavar="YYYY-MM-DD",\n                    help="依據某一天的收盤回放（驗證用）")\n    ap.add_argument("--full", action="store_true",\n                    help="完整版（六個區塊）。預設是只有觸發點位的精簡版")\n    ap.add_argument("--note", default="",\n                    help="在訊息開頭加一行提示，例如標明這是回放而非即時訊號")\n    args = ap.parse_args(argv)\n\n    login()\n    as_of = (date.fromisoformat(args.as_of) if args.as_of else None)\n    note = args.note or ("⚠️ **這是回放，不是即時訊號**" if as_of else "")\n    if not 0.0 <= args.core_band < 1.0:\n        raise SystemExit("--core-band 必須在 [0, 1) 之間")\n    d = Daily(PRESETS[args.preset], args.max_leverage, as_of, note,\n              sizing=args.sizing, step_down=not args.no_step_down,\n              core_band=args.core_band)\n\n    lag = (date.today() - d.last.d).days\n    if as_of is None and lag > args.stale_days:\n        print(f"⚠️ 資料只到 {d.last.d}（落後 {lag} 天），FinLab 可能尚未更新",\n              file=sys.stderr)\n\n    if args.only_if_action and not d.has_action():\n        print(f"{d.last.d} 沒有動作也沒有接近觸發，不送出。")\n        return 0\n\n    p = d.payload(args.full)\n    if args.dry_run or not args.webhook:\n        if not args.webhook and not args.dry_run:\n            print("未設定 DISCORD_WEBHOOK_URL，改為只印出：\\n", file=sys.stderr)\n        print(render_text(p))\n        return 0\n    try:\n        post(args.webhook, p)\n    except (urllib.error.URLError, RuntimeError) as exc:\n        print(f"送出失敗：{exc}", file=sys.stderr)\n        return 1\n    print(f"已送出 {d.last.d} 的每日訊號。")\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'
_SOURCES['scripts/discord_notify.py'] = '#!/usr/bin/env python3\n"""送一則簡單訊息到 Discord webhook。**不依賴任何第三方套件。**\n\n    python3 scripts/discord_notify.py --title "標題" --text "內文" --color red\n\n給 CI 的失敗通知用 —— 那個時間點 finlab / pandas 可能還沒裝好，\n所以這支刻意只用標準函式庫，也刻意與 discord_daily.py 分開。\n\n⚠️ 一定要帶 User-Agent。Discord 會對 urllib 的預設 UA（`Python-urllib/x.y`）\n回 403 Forbidden，症狀是本機測試正常、放到 CI 就失敗。\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport sys\nimport urllib.error\nimport urllib.request\n\nUA = "tw-backdraw-daily/1.0 (+https://github.com/swhunag65221-pixel/joe_TWbackdraw)"\nCOLORS = {"red": 0xE74C3C, "green": 0x2ECC71, "yellow": 0xF1C40F,\n          "blue": 0x3498DB, "grey": 0x95A5A6}\n\n\ndef send(webhook: str, title: str, text: str, colour: int) -> None:\n    body = {"embeds": [{"title": title, "description": text, "color": colour}]}\n    req = urllib.request.Request(\n        webhook, data=json.dumps(body).encode("utf-8"),\n        headers={"Content-Type": "application/json", "User-Agent": UA})\n    with urllib.request.urlopen(req, timeout=30) as r:\n        if r.status not in (200, 204):\n            raise RuntimeError(f"Discord 回應 {r.status}")\n\n\ndef main() -> int:\n    ap = argparse.ArgumentParser(description="送一則訊息到 Discord")\n    ap.add_argument("--webhook", required=True)\n    ap.add_argument("--title", required=True)\n    ap.add_argument("--text", default="")\n    ap.add_argument("--color", default="grey", choices=sorted(COLORS))\n    args = ap.parse_args()\n\n    if not args.webhook:\n        print("沒有 webhook，略過通知")\n        return 0\n    try:\n        send(args.webhook, args.title, args.text, COLORS[args.color])\n    except (urllib.error.URLError, RuntimeError) as exc:\n        print(f"通知送出失敗：{exc}", file=sys.stderr)\n        return 1\n    print("通知已送出")\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'

